export const OVERLAYS = {"equine-repro--eqrepro-anatomy-cycle":{"equine-repro--eqrepro-anatomy-cycle--รังไข่ม้ากลับด้าน-และ-ovulation-fossa":{"claims":[{"id":"equine-repro--eqrepro-anatomy-cycle--รังไข่ม้ากลับด้าน-และ-ovulation-fossa--v1","statement":"รังไข่ม้ามีลักษณะเฉพาะที่ต่างจากสัตว์เลี้ยงชนิดอื่น คือมี ovulation fossa ร่วมกับการสลับตำแหน่งของชั้น cortex และ medulla (cortical-medullary inversion)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-41542794","locator":"Abstract, opening sentence","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The equine ovary exhibits unique structural and developmental features that distinguish it from those of other domestic species, including the presence of an ovulation fossa and an inversion of cortical and medullary layers."}},{"id":"equine-repro--eqrepro-anatomy-cycle--รังไข่ม้ากลับด้าน-และ-ovulation-fossa--v2","statement":"การสร้างภาพสามมิติของรังไข่ม้าแสดงว่า ovulation fossa อยู่กลางรังไข่ ล้อมด้วย cortex ที่กว้าง ส่วน medulla อยู่บริเวณรอบนอกที่แคบ และพบร่องรอยการตกไข่เฉพาะที่ ovulation fossa เท่านั้น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-11688742","locator":"Vol 30(5):309-12, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The ovulation fossa is localized in the centre of the ovary and is surrounded by a broad ovarian cortex. A trace of ovulation was observed only at the ovulation fossa. Medulla are localized in narrow peripheral areas."}}]},"equine-repro--eqrepro-anatomy-cycle--ตัวเลขในวงรอบที่เฉลยระบุไว้":{"claims":[{"id":"equine-repro--eqrepro-anatomy-cycle--ตัวเลขในวงรอบที่เฉลยระบุไว้--v1","statement":"corpus luteum ของม้าจะเจริญเต็มที่และตอบสนองต่อ prostaglandin ประมาณ 5 วันหลังตกไข่ ตรงกับที่เอกสารระบุว่าตอบสนองเมื่ออายุ 5 ถึง 6 วันขึ้นไป","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-veterinary-manua-2024","locator":"Section on the equine oestrous cycle, revised Sept 2024 by Patricia L. Sertich","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"This corpus luteum will be mature and become responsive to prostaglandin in ~5 days."}},{"id":"equine-repro--eqrepro-anatomy-cycle--ตัวเลขในวงรอบที่เฉลยระบุไว้--v2","statement":"ม้าส่วนใหญ่เป็น seasonally polyestrous และเข้าวงรอบเมื่อช่วงกลางวันยาว","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-veterinary-manua-2024","locator":"Section on seasonality of the equine cycle, revised Sept 2024","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Most mares are seasonally polyestrous and cycle when the length of daylight is long."}},{"id":"equine-repro--eqrepro-anatomy-cycle--ตัวเลขในวงรอบที่เฉลยระบุไว้--v3","statement":"แหล่งอ้างอิงระบุเกณฑ์ขนาดฟอลลิเคิลเด่นที่ตกไข่ไว้ที่ ตั้งแต่ 30 มม. ขึ้นไป ซึ่งกว้างกว่าตัวเลข 3.5 ถึง 4 ซม. ที่เอกสารระบุ ตัวเลขของเอกสารจึงอยู่ในช่วงฟอลลิเคิลที่โตเต็มที่ แต่ไม่ใช่เกณฑ์ขั้นต่ำ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-veterinary-manua-2024","locator":"Section on follicular development, revised Sept 2024","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Usually, one follicle becomes dominant and ovulates when it is ≥30 mm in diameter."}}]},"equine-repro--eqrepro-anatomy-cycle--แสง-เมลาโทนิน-และการกลับมาเป็นสัด":{"claims":[{"id":"equine-repro--eqrepro-anatomy-cycle--แสง-เมลาโทนิน-และการกลับมาเป็นสัด--v1","statement":"การให้แสง 16 ชั่วโมงต่อวันช่วยเร่งให้ม้ากลับมาตกไข่และเข้าวงรอบสม่ำเสมอ โดยต้องใช้เวลา 8 ถึง 10 สัปดาห์กว่าจะตอบสนอง","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-veterinary-manua-2024","locator":"Section on manipulation of the breeding season, revised Sept 2024","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The onset of ovulation and subsequent regular estrous cycles...can be hastened by exposing the mare to 16 hours of light per day; 8–10 weeks are required for mares to respond."}},{"id":"equine-repro--eqrepro-anatomy-cycle--แสง-เมลาโทนิน-และการกลับมาเป็นสัด--v2","statement":"ในม้า ระดับเมลาโทนินสูงขึ้นเฉพาะช่วงมืด และช่วงเวลาที่เมลาโทนินสูงจะยาวที่สุดในฤดูหนาว จึงเป็นสัญญาณบอกความยาววันตามที่เอกสารอธิบายว่าวันสั้นทำให้เมลาโทนินสูง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-8609596","locator":"Vol 19(1):7-15, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The duration of elevated melatonin was not different from the duration of natural scotophase for each season, with the duration of elevated melatonin longer in winter than the other seasons."}},{"id":"equine-repro--eqrepro-anatomy-cycle--แสง-เมลาโทนิน-และการกลับมาเป็นสัด--v3","statement":"สัญญาณเมลาโทนินไม่ได้ไปกดเซลล์ GnRH โดยตรง แต่ถูกแปลสัญญาณที่ pars tuberalis ของต่อมใต้สมองผ่าน melatonin receptor ก่อนส่งผลต่อแกน hypothalamic-pituitary-gonadal ในม้า ลูกโซ่ที่เอกสารเขียนจึงถูกในภาพรวมแต่ย่อขั้นกลางออกไป","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-40785101","locator":"Vol 37(10):e70077, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The hypophyseal pars tuberalis (PT) has been indicated as a critical site for the transduction of melatonin signals through melatonin-responsive, PT-specific cells that produce thyroid-stimulating hormone (TSH) in many mammalian species."}}]}},"equine-repro--eqrepro-art-female":{"equine-repro--eqrepro-art-female--การกระตุ้นตกไข่และการผสมเทียม":{"claims":[{"id":"equine-repro--eqrepro-art-female--การกระตุ้นตกไข่และการผสมเทียม--v1","statement":"การกระตุ้นตกไข่ในม้าใช้ human chorionic gonadotropin (hCG) เป็นมาตรฐาน ร่วมกับทางเลือกอื่นคือ recombinant LH และ GnRH analogue deslorelin โดยเฉลี่ยตกไข่ประมาณ 36 ชั่วโมงหลังให้ยา","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-18554709","locator":"Vol 70(3):445-7, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Ovulation is routinely induced with human chorionic gonadotropin (hCG), recombinant LH (rLH), or the GnRH analogue Deslorelin. On average, ovulation occurs approximately 36h after treatment"}},{"id":"equine-repro--eqrepro-art-female--การกระตุ้นตกไข่และการผสมเทียม--v2","statement":"การผสมเทียมม้าปล่อยน้ำเชื้อเข้าที่ตัวมดลูก (body of the uterus) ผ่านท่อผสมเทียมพลาสติกปลอดเชื้อ ตรงกับที่เฉลยแก้จาก intracervix","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-veterinary-manua-2024","locator":"Section on artificial insemination, revised Sept 2024 by Patricia L. Sertich","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Insemination is accomplished by depositing the semen into the body of the uterus using a sterile, plastic insemination pipette."}},{"id":"equine-repro--eqrepro-art-female--การกระตุ้นตกไข่และการผสมเทียม--v3","statement":"PGE2 คลายกล้ามเนื้อเรียบของ isthmus ในท่อนำไข่ม้า และการหยด PGE2 เฉพาะที่ผิวท่อนำไข่เร่งการเคลื่อนของตัวอ่อนผ่านท่อนำไข่ได้จริง จึงเป็นเหตุผลที่ใช้ PGE ไม่ใช่ oxytocin ในการแก้ปัญหาการติดค้างที่ท่อนำไข่","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20681173","locator":"Issue 56:587-92, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"It is thought that further onward movement of embryos to the uterus is facilitated by secretion of prostaglandin E2 (PGE2) by the embryos, which relaxes the smooth muscle of the isthmus."}}]},"equine-repro--eqrepro-art-female--การเก็บ-ย้ายฝาก-และแช่แข็งตัวอ่อน":{"claims":[{"id":"equine-repro--eqrepro-art-female--การเก็บ-ย้ายฝาก-และแช่แข็งตัวอ่อน--v1","statement":"ตัวอ่อนม้าที่เก็บได้ในวันที่ 7 ถึง 8 หลังตกไข่ทั้งหมดอยู่ในระยะ expanding blastocyst ขณะที่ตัวอ่อนที่เก็บวันที่ 5 ยังเป็น compacted morula","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20681173","locator":"Issue 56:587-92, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"All of the embryos recovered on day 5 were compacted morulae, whereas all of those recovered on days 7 or 8 were expanding blastocysts."}},{"id":"equine-repro--eqrepro-art-female--การเก็บ-ย้ายฝาก-และแช่แข็งตัวอ่อน--v2","statement":"การแช่แข็งตัวอ่อนม้าที่ขนาดใหญ่กว่า 300 ไมโครเมตร ให้อัตราการตั้งท้องต่ำมาโดยตลอด จนกระทั่งมีการเจาะยุบและดูดของเหลวใน blastocoele ออกก่อน vitrification ยืนยันว่า expanded blastocyst ทนการแช่แข็งได้ไม่ดี","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30417442","locator":"Vol 51(4):500-505, Background","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Historically, cryopreservation of equine embryos >300 μm gave poor pregnancy rates until researchers collapsed the blastocoele cavity and aspirated the blastocoele fluid prior to vitrification."}},{"id":"equine-repro--eqrepro-art-female--การเก็บ-ย้ายฝาก-และแช่แข็งตัวอ่อน--v3","statement":"อัตราการตั้งท้องหลังแช่แข็ง blastocyst ม้าขนาดใหญ่ยังต่ำกว่าปศุสัตว์ชนิดอื่น โดยเชื่อว่า embryonic capsule เป็นด่านหลักที่กั้นไม่ให้ cryoprotectant เข้าสู่ตัวอ่อน ซึ่งเป็นกลไกอธิบายว่าทำไม expanded blastocyst จึงรอดต่ำ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26639642","locator":"Vol 85(5):894-903, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Pregnancy rates after cryopreservation of large equine blastocyst stage embryos have remained lower than other domesticated livestock species. It is generally accepted that the embryonic capsule is the primary barrier to cryoprotectant entr"}},{"id":"equine-repro--eqrepro-art-female--การเก็บ-ย้ายฝาก-และแช่แข็งตัวอ่อน--v4","statement":"อัตราการตั้งท้องมีแนวโน้มสูงกว่าในตัวรับที่ตกไข่วันเดียวกับตัวให้หรือก่อนตัวให้ สนับสนุนหลักการซิงโครไนซ์การตกไข่ระหว่างตัวให้และตัวรับ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16726194","locator":"Vol 26(3):291-8, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Pregnancy rates tended (P < 0.1) to be greater in recipients that were detected to be ovulating the same day or prior to that of the donor"}}]},"equine-repro--eqrepro-art-female--somatic-cell-nuclear-transfer-cloning":{"claims":[{"id":"equine-repro--eqrepro-art-female--somatic-cell-nuclear-transfer-cloning--v1","statement":"ลูกม้าโคลนมีลายพิมพ์ microsatellite DNA ตรงกับเซลล์ต้นแบบทุกตำแหน่ง แต่ mitochondrial DNA ตรงกับม้าที่ให้โอโอไซต์ ไม่ใช่เซลล์ต้นแบบ จึงไม่ใช่สำเนาพันธุกรรม 100 เปอร์เซ็นต์ตามที่เอกสารระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26119166","locator":"Vol 16(4):509-16, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"There was a perfect identity match between the cloned foal and the cell donor after analysis of microsatellite DNA, and the mitochondrial DNA of the cloned foal was identical with that of the oocyte donor."}},{"id":"equine-repro--eqrepro-art-female--somatic-cell-nuclear-transfer-cloning--v2","statement":"จีโนมไมโทคอนเดรียไม่ถูกส่งต่อไปกับการโคลน จึงถูกใช้เป็นวิธีตรวจจับการโคลนในวงการแข่งม้า โดยเทียบลำดับไมโทคอนเดรียของลูกม้ากับแม่ที่ขึ้นทะเบียนไว้ ซึ่งเป็นข้อจำกัดเชิงระเบียบพันธุ์ที่เอกสารกล่าวถึง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35362263","locator":"Vol 14(8):1429-1437, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"One possible method involves the characterisation of the mitochondrial genome (which is not routinely preserved during cloning) and comparing it with the sequence of the registered dam."}}]}},"equine-repro--eqrepro-endometritis":{"equine-repro--eqrepro-endometritis--ตารางแยก-7-ภาวะของมดลูกม้าที่ทำให้ผสมไม่ติด":{"claims":[{"id":"equine-repro--eqrepro-endometritis--ตารางแยก-7-ภาวะของมดลูกม้าที่ทำให้ผสมไม่ติด--v1","statement":"endometrosis ในม้ามีลักษณะเด่นคือ periglandular fibrosis เป็นสาเหตุของภาวะสมบูรณ์พันธุ์ต่ำที่พบบ่อย และปัจจุบันยังไม่มีการรักษาที่ได้ผล ตรงกับที่เอกสารระบุว่ารักษาไม่หาย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30907027","locator":"Vol 54(6):835-845, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Equine endometrosis, a frequent cause of subfertility, is characterized by periglandular fibrosis, and no treatment exists."}},{"id":"equine-repro--eqrepro-endometritis--ตารางแยก-7-ภาวะของมดลูกม้าที่ทำให้ผสมไม่ติด--v2","statement":"metritis คือการอักเสบของผนังมดลูกทุกชั้น ทั้ง endometrium myometrium และ perimetrium ขณะที่ endometritis เป็นการอักเสบตื้นเฉพาะชั้น endometrium ซึ่งอธิบายว่าทำไม metritis จึงเป็นภาวะเดียวในตารางที่ม้าป่วยทั้งระบบ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-37191856","locator":"Vol 58 Suppl 2:49-71, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Metritis is associated with inflammation of all uterine layers (endometrium, myometrium and perimetrium), whereas endometritis is a more superficial inflammation involving solely the endometrium."}},{"id":"equine-repro--eqrepro-endometritis--ตารางแยก-7-ภาวะของมดลูกม้าที่ทำให้ผสมไม่ติด--v3","statement":"อาการที่ใช้วินิจฉัย endometritis ทั่วไป เช่น ของเหลวในมดลูก vaginal discharge และช่วงเป็นสัดสั้นลง อาจไม่ปรากฏเลยใน subclinical endometritis ยืนยันว่าภาวะนี้แยกได้ด้วยการเก็บตัวอย่างจากเยื่อบุมดลูกไม่ใช่ด้วยอาการ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19660076","locator":"Vol 44 Suppl 3:10-22, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Diagnosis is made through detecting uterine fluid, vaginitis, vaginal discharge, short inter-oestrous intervals, inflammatory uterine cytology and positive uterine culture. However, these signs may be absent in subclinical cases."}},{"id":"equine-repro--eqrepro-endometritis--ตารางแยก-7-ภาวะของมดลูกม้าที่ทำให้ผสมไม่ติด--v4","statement":"pyometra ในม้าเกิดตามหลังพังผืดปิดกั้นรูคอมดลูก (transluminal cervical adhesions) ทำให้มดลูกขยายและพบของเหลว echogenic คั่ง ตรงกับที่เอกสารระบุว่า cervix ปิดจึงไม่มี discharge","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26043134","locator":"Vol 246(12):1354-7, Clinical findings","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"palpation per rectum of the reproductive tract revealed uterine distention, and transrectal ultrasonography confirmed the presence of echogenic fluid accumulation within the uterus. Cervical palpation during vaginal speculum examination ind"}}]},"equine-repro--eqrepro-endometritis--เกณฑ์-intraluminal-fluid-หลังผสม":{"claims":[{"id":"equine-repro--eqrepro-endometritis--เกณฑ์-intraluminal-fluid-หลังผสม--v1","statement":"การศึกษาย้อนหลัง 1,745 รอบการผสมในม้า warmblood นิยาม PBIE ว่าคือการตรวจพบของเหลวในโพรงมดลูกมากกว่า 2 ซม. ตั้งแต่วันถัดจากวันผสม ยืนยันเกณฑ์ 2 ซม. ที่เขียนทับด้วยลายมือ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-42033022","locator":"Methods, case definition","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"PBIE was defined as the detection of >2 cm intrauterine fluid from the day after insemination."}}]},"equine-repro--eqrepro-endometritis--goal-1-evacuate-contents":{"claims":[{"id":"equine-repro--eqrepro-endometritis--goal-1-evacuate-contents--v1","statement":"การรักษามาตรฐานของ endometritis หลังผสมประกอบด้วย uterine lavage หลังผสม oxytocin และยาปฏิชีวนะในมดลูก โดยมี cloprostenol และ carbetocin เป็นยาบีบมดลูกที่เพิ่มเข้ามาได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19660076","locator":"Vol 44 Suppl 3:10-22, Treatment section of abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Treatments that may be added to traditional therapies, such as post-breeding uterine lavage, oxytocin and intrauterine antibiotics, include lavage 1-h before mating, carbetocin, cloprostenol, cervical dilators"}}]},"equine-repro--eqrepro-endometritis--goal-2-control-infection-ตารางสเปกตรัมยาปฏิชีวนะ":{"claims":[{"id":"equine-repro--eqrepro-endometritis--goal-2-control-infection-ตารางสเปกตรัมยาปฏิชีวนะ--v1","statement":"แบคทีเรียที่ไม่สามารถทำ electron transport ที่พึ่งออกซิเจนหรือไนเตรตได้ จะดื้อต่อ streptomycin และ gentamicin เพราะขนส่งยาเข้าเซลล์ไม่ได้ ยืนยันว่า aminoglycosides ต้องอาศัยออกซิเจนจึงจะออกฤทธิ์ได้ดี","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-218500","locator":"Vol 15(1):7-13, Abstract conclusion","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"These results demonstrate that anaerobic bacteria unable to carry out oxygen- or nitrate-dependent electron transport are resistant to streptomycin and gentamicin because of failure to transport aminoglycosides."}},{"id":"equine-repro--eqrepro-endometritis--goal-2-control-infection-ตารางสเปกตรัมยาปฏิชีวนะ--v2","statement":"ceftiofur ที่ให้เข้ากล้ามในม้าคงระดับยาในเนื้อเยื่อ endometrium สูงกว่า MIC ของ Streptococcus equi subsp. zooepidemicus และ Escherichia coli ได้ถึง 24 ชั่วโมง ซึ่งครอบคลุมทั้งเชื้อ Gram บวกและ Gram ลบหลักของ bacterial endometritis","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20494421","locator":"Vol 74(3):466-72, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"remained above the reported MIC for Streptococcus equi zooepidemicus and Escherichia coli in both serum and endometrial tissue until 24 h after treatment"}},{"id":"equine-repro--eqrepro-endometritis--goal-2-control-infection-ตารางสเปกตรัมยาปฏิชีวนะ--v3","statement":"polymyxin B ในเลือดม้ามีฤทธิ์ลบล้าง endotoxin โดยวัดจากความสามารถกดการตอบสนองของแมโครฟาจต่อ lipopolysaccharide และใช้เป็นการรักษา endotoxemia ยืนยันจุดเด่นที่ตารางระบุว่าจับ LPS ได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16579757","locator":"Vol 67(4):642-7, Methods and conclusion","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Polymyxin B concentration was measured as the ability to suppress nitrite production by murine macrophages stimulated with lipopolysaccharide and interferon-alpha... Results support repeated IV use of 1 mg of polymyxin B/kg at 8-hour interv"}}]},"equine-repro--eqrepro-endometritis--goal-3-moderate-inflammation":{"claims":[{"id":"equine-repro--eqrepro-endometritis--goal-3-moderate-inflammation--v1","statement":"ยาที่ใช้เสริมการรักษา endometritis ในม้ารวมถึงกลุ่ม mucolytic ได้แก่ DMSO kerosene และ N-acetylcysteine ร่วมกับ corticosteroid เช่น prednisolone และ dexamethasone ตรงกับรายการใน Goal 3","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19660076","locator":"Vol 44 Suppl 3:10-22, Treatment section of abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"intrauterine chelators (EDTA-Tris), mucolytics (DMSO, kerosene, N-acetylcysteine), corticosteroids (prednisolone, dexamethasone) and immunomodulators"}},{"id":"equine-repro--eqrepro-endometritis--goal-3-moderate-inflammation--v2","statement":"N-acetylcysteine เป็น mucolytic ที่มีฤทธิ์ต้านการอักเสบ และการหยอดสารละลาย 3.3 เปอร์เซ็นต์เข้ามดลูกไม่ระคายเคือง พร้อมทั้งยับยั้ง oxidative burst ของนิวโทรฟิล","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-23623166","locator":"Vol 80(3):218-27, Conclusion","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"intrauterine infusion of a 3.3% solution of NAC was not irritating and inhibited the oxidative burst of neutrophils"}},{"id":"equine-repro--eqrepro-endometritis--goal-3-moderate-inflammation--v3","statement":"การหยอด platelet rich plasma เข้ามดลูกช่วยลดการอักเสบที่มากเกินไปหลังผสมในม้าที่มี chronic degenerative endometritis โดยลดสัดส่วนนิวโทรฟิลใน cytology และของเหลวคั่งในมดลูก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27020400","locator":"Vol 86(2):516-22, Conclusion","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"we can conclude that PRP was effective in modulating the exacerbated uterine inflammatory response to semen in mares with CDE"}}]},"equine-repro--eqrepro-endometritis--goal-4-prevent-recurrence-และภูมิคุ้มกันของมดลูกม้า":{"claims":[{"id":"equine-repro--eqrepro-endometritis--goal-4-prevent-recurrence-และภูมิคุ้มกันของมดลูกม้า--v1","statement":"โครงสร้างปากช่องคลอดที่ผิดรูปทำให้ม้าเสี่ยงต่อการติดเชื้อในมดลูก และการทำ vulvoplasty ปิดริมฝีปากช่องคลอดส่วนบน (Caslick) เพิ่มความสมบูรณ์พันธุ์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16268960","locator":"Vol 52(9):474-7, Abstract opening","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Changes in the conformation of the vulva predispose the mare to uterine infection. Vulvoplasty for closure of the upper vulvar lips improves fertility."}},{"id":"equine-repro--eqrepro-endometritis--goal-4-prevent-recurrence-และภูมิคุ้มกันของมดลูกม้า--v2","statement":"Toll-like receptors เป็นตัวรับข้ามเยื่อหุ้มเซลล์ในระบบภูมิคุ้มกันโดยกำเนิด ทำหน้าที่รู้จำแอนติเจนและสัมพันธ์กับ endometritis ในม้า ยืนยันบทบาทของ pattern recognition receptor ในภาพกลไกป้องกันของมดลูก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39396880","locator":"Vol 59 Suppl 3:e14657, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Toll-like receptors (TLRs) are transmembrane receptors involved in the innate immune response, recognized for their role in antigen recognition and previously associated with equine endometritis."}},{"id":"equine-repro--eqrepro-endometritis--goal-4-prevent-recurrence-และภูมิคุ้มกันของมดลูกม้า--v3","statement":"ม้าที่ไวต่อ persistent mating-induced endometritis แสดงออกของยีนภูมิคุ้มกันโดยกำเนิดและ antimicrobial peptide ในเยื่อบุมดลูกสูงกว่ากลุ่มควบคุม สนับสนุนว่ามดลูกม้าอาศัย innate immune เป็นแกนหลักในการป้องกัน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28834688","locator":"Vol 30(3):533-545, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Genes for C-C motif chemokine ligand 2 (CCL2) and the antimicrobial peptides secreted phospholipase A2 (sPLA2), lipocalin 2 and lactoferrin were all expressed at higher levels in susceptible compared with control mares."}}]},"equine-repro--eqrepro-endometritis--pyometra-แนวทางรักษา":{"claims":[{"id":"equine-repro--eqrepro-endometritis--pyometra-แนวทางรักษา--v1","statement":"prostaglandin ถูกใช้รักษา pyometra และ chronic endometritis ในสัตว์เศรษฐกิจเพศเมียรวมถึงม้า ร่วมกับข้อบ่งใช้อื่นเช่นการซิงโครไนซ์การเป็นสัดและการยุติ pseudopregnancy ในม้า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16490704","locator":"Vol 171(2):206-28, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"they are used to synchronize oestrus, terminate pseudopregnancy in mares, induce parturition, and treat retained placenta, luteinized cysts, pyometra, and chronic endometritis."}},{"id":"equine-repro--eqrepro-endometritis--pyometra-แนวทางรักษา--v2","statement":"การรักษาแบบอนุรักษ์ของ pyometra ในม้าคือการระบายและล้างมดลูกร่วมกับยาปฏิชีวนะและยาต้านการอักเสบทั่วร่างกาย ส่วน ovariohysterectomy เป็นการผ่าตัดที่เลือกใช้ ตรงกับที่เอกสารจัด hysterectomy เป็นทางเลือกสุดท้าย และภาวะนี้มีแนวโน้มกลับเป็นซ้ำ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31145499","locator":"Vol 54(8):1155-1159, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Ovariohysterectomy is the surgical procedure of choice. Conservative therapy consists of draining and flushing the uterus, and systemic anti-inflammatory and antimicrobial treatment."}}]},"equine-repro--eqrepro-endometritis--เคสตัวอย่างที่รุ่นพี่บันทึกไว้-ม้า-7-ปี-ผสมไม่ติด-3-ครั้ง":{"claims":[{"id":"equine-repro--eqrepro-endometritis--เคสตัวอย่างที่รุ่นพี่บันทึกไว้-ม้า-7-ปี-ผสมไม่ติด-3-ครั้ง--v1","statement":"การเปิดของคอมดลูกจำเป็นต่อการระบายของมดลูกหลังผสม และคอมดลูกที่ไม่คลายหรือปิดเร็วเกินไปนำไปสู่ endometritis เรื้อรัง โดยการทดลองปิดคอมดลูกหลังผสมทำให้ของเหลวและนิวโทรฟิลคั่งมากขึ้นจริง ซึ่งเป็นเหตุผลที่การพบของเหลวคั่งขณะคอมดลูกปิดในระยะ diestrus ถือว่าผิดปกติ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26586278","locator":"Vol 85(4):617-24, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Cervical patency is considered to be important for uterine drainage after mating or artificial insemination (AI), and failure to relax or premature tightening of the cervix can lead to persistent endometritis."}},{"id":"equine-repro--eqrepro-endometritis--เคสตัวอย่างที่รุ่นพี่บันทึกไว้-ม้า-7-ปี-ผสมไม่ติด-3-ครั้ง--v2","statement":"การสำรวจ swab มดลูกม้า 452 ตัวอย่างพบ Escherichia coli ร้อยละ 29.7 และ Streptococcus equi subsp. zooepidemicus ร้อยละ 15.2 โดยทั้งคู่สัมพันธ์กับ equine endometritis จึงสนับสนุนการวินิจฉัย bacterial endometritis เมื่อเพาะขึ้น E. coli ร่วมกับ Staphylococcus","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33582824","locator":"Vol 44(1):19-23, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the prevalence of isolated bacteria included E. coli (29.7%) and Streptococcus equi subsp. zooepidemicus (15.2%), both frequently associated with equine endometritis."}}]},"equine-repro--eqrepro-endometritis--หน้าที่ของมดลูกและ-endometrium":{"claims":[{"id":"equine-repro--eqrepro-endometritis--หน้าที่ของมดลูกและ-endometrium--v1","statement":"ใน endometrium ของม้า oxytocin receptor และ PTGS2 เป็นองค์ประกอบหลักของ luteolytic pathway ที่ทำให้ PGF2α หลั่งในรอบสัด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24679480","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Endometrial oxytocin receptors (OXTR) and prostaglandin-endoperoxide synthase 2 (PTGS2) are central components of the luteolytic pathway in cyclic mares"}}]},"equine-repro--eqrepro-endometritis--contamination-กับ-infection":{"claims":[{"id":"equine-repro--eqrepro-endometritis--contamination-กับ-infection--v1","statement":"Spermatozoa กระตุ้น PMN เข้ามาใน lumen ของมดลูก จึง endometritis ชั่วคราวหลังผสมเป็นปฏิกิริยาปกติทางสรีรวิทยา","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10734380","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Recent studies have demonstrated that spermatozoa trigger PMN chemotaxis into the uterine lumen. This observation suggests that a transient endometritis is a normal physiological response to breeding."}}]},"equine-repro--eqrepro-endometritis--กลไกป้องกันของมดลูก":{"claims":[{"id":"equine-repro--eqrepro-endometritis--กลไกป้องกันของมดลูก--v1","statement":"การเสียกลไก physical clearance ของมดลูกเชื่อว่ามีบทบาทหลักต่อความไวต่อ persistent endometritis ในม้า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10734380","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A breakdown of uterine physical clearance mechanisms is currently believed to play a major role in susceptibility to persistent endometritis."}}]},"equine-repro--eqrepro-endometritis--นิยามของ-endometritis-และภาวะที่ใกล้เคียง":{"claims":[{"id":"equine-repro--eqrepro-endometritis--นิยามของ-endometritis-และภาวะที่ใกล้เคียง--v1","statement":"Metritis คือการอักเสบของมดลูกทุกชั้น ส่วน endometritis เป็นการอักเสบตื้นกว่าที่เกิดเฉพาะ endometrium","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-37191856","locator":"abstract","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Metritis is associated with inflammation of all uterine layers (endometrium, myometrium and perimetrium), whereas endometritis is a more superficial inflammation involving solely the endometrium."}}]},"equine-repro--eqrepro-endometritis--ชนิดของ-endometritis-และ-pbie":{"claims":[{"id":"equine-repro--eqrepro-endometritis--ชนิดของ-endometritis-และ-pbie--v1","statement":"การระบายน้ำเชื้อออกไม่ดีหรือภูมิคุ้มกันไม่พอ อาจทำให้เกิด persistent mating-induced endometritis","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-37191856","locator":"abstract","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Improper drainage of the ejaculatory fluid or an inadequate immune response may result in persistent mating-induced endometritis."}}]},"equine-repro--eqrepro-endometritis--ปัจจัยเสี่ยงและเชื้อที่เกี่ยวข้อง":{"claims":[{"id":"equine-repro--eqrepro-endometritis--ปัจจัยเสี่ยงและเชื้อที่เกี่ยวข้อง--v1","statement":"ความผิดปกติของกายวิภาคอวัยวะเพศ การบีบตัวของ myometrium การระบายน้ำเหลือง cervix และการเสื่อมตามวัย เป็นพื้นฐานของความไวต่อ endometritis ในแม่ม้า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19660076","locator":"abstract","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Defects in genital anatomy, myometrial contractions, lymphatic drainage, mucociliary clearance, cervical function, plus vascular degeneration and inflamm-ageing underlie susceptibility to endometritis."}}]},"equine-repro--eqrepro-endometritis--ผลของ-endometritis-ต่อ-fertility":{"claims":[{"id":"equine-repro--eqrepro-endometritis--ผลของ-endometritis-ต่อ-fertility--v1","statement":"Endometritis เป็นสาเหตุสำคัญของ infertility ในม้า เกิดจากการกำจัดเชื้อ sperm และ exudate หลังผสมไม่สำเร็จ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19660076","locator":"abstract","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Endometritis, a major cause of mare infertility arising from failure to remove bacteria, spermatozoa and inflammatory exudate post-breeding, is often undiagnosed."}}]},"equine-repro--eqrepro-endometritis--adverse-outcomes-การอักเสบกระทบระบบสืบพันธุ์อย่างไร":{"claims":[{"id":"equine-repro--eqrepro-endometritis--adverse-outcomes-การอักเสบกระทบระบบสืบพันธุ์อย่างไร--v1","statement":"Endometritis ทั้งหลังคลอดและหลังผสมทำให้สภาพแวดล้อมของตัวอ่อนและ placenta ไม่เหมาะสม และอาจกระทบการอยู่รอดของ sperm","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-37191856","locator":"abstract","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Both postpartum and postmating endometritis interferes with fertility by creating a suboptimal environment for embryo development and placentation, and chronic endometritis may have an impact on sperm survival and fertilization ability."}}]},"equine-repro--eqrepro-endometritis--การวินิจฉัย-clinical-และ-subclinical-endometritis":{"claims":[{"id":"equine-repro--eqrepro-endometritis--การวินิจฉัย-clinical-และ-subclinical-endometritis--v1","statement":"การวินิจฉัย endometritis ในม้าอาศัย uterine fluid, vaginal discharge, cytology และ culture","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19660076","locator":"abstract","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Diagnosis is made through detecting uterine fluid, vaginitis, vaginal discharge, short inter-oestrous intervals, inflammatory uterine cytology and positive uterine culture."}}]},"equine-repro--eqrepro-endometritis--ultrasonography":{"claims":[{"id":"equine-repro--eqrepro-endometritis--ultrasonography--v1","statement":"แม่ม้าที่เป็น subclinical endometritis ต้องติดตามด้วย ultrasound หลังผสม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19660076","locator":"abstract","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Mares with subclinical endometritis require careful monitoring by ultrasound post-breeding."}}]},"equine-repro--eqrepro-endometritis--culture-cytology-และ-biopsy":{"claims":[{"id":"equine-repro--eqrepro-endometritis--culture-cytology-และ-biopsy--v1","statement":"Cytology ของ endometrium พบม้าที่มีการอักเสบเฉียบพลันได้เป็นสองเท่าของ culture swab และ culture จาก biopsy หรือ uterine fluid ไวกว่า swab","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20591061","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Culturing endometrial biopsy tissue or uterine fluids are more sensitive methods for identifying Escherichia coli than culture swab while endometrial cytology identifies twice as many mares with acute inflammation than uterine culture swab."}}]},"equine-repro--eqrepro-endometritis--diagnostic-decision-tree":{"claims":[{"id":"equine-repro--eqrepro-endometritis--diagnostic-decision-tree--v1","statement":"Uterine cytology ไวกว่า culture สองเท่าในการตรวจ endometritis จึงพบการอักเสบได้แม้ culture ไม่พบเชื้อ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19660076","locator":"abstract","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"uterine cytology is twice as sensitive as culture in detecting endometritis."}}]},"equine-repro--eqrepro-endometritis--treatment-ภาพรวม-และเป้าหมายที่-1-ระบายสิ่งที่คั่งในมดลูก":{"claims":[{"id":"equine-repro--eqrepro-endometritis--treatment-ภาพรวม-และเป้าหมายที่-1-ระบายสิ่งที่คั่งในมดลูก--v1","statement":"Post-mating-induced endometritis รักษามาตรฐานด้วย uterine irrigation และ ecbolics","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20591061","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"post-mating-induced endometritis is classically treated with uterine irrigation and ecbolics"}}]},"equine-repro--eqrepro-endometritis--เป้าหมายที่-2-คุมการติดเชื้อด้วย-antibiotics":{"claims":[{"id":"equine-repro--eqrepro-endometritis--เป้าหมายที่-2-คุมการติดเชื้อด้วย-antibiotics--v1","statement":"Acute endometritis รักษาได้ด้วย antibiotics แบบ systemic หรือใส่เข้ามดลูก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20591061","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"acute endometritis is treated with either systemic or intra-uterine antibiotics"}}]},"equine-repro--eqrepro-endometritis--เป้าหมายที่-3-ลดการอักเสบ-และการรักษาทางเลือก":{"claims":[{"id":"equine-repro--eqrepro-endometritis--เป้าหมายที่-3-ลดการอักเสบ-และการรักษาทางเลือก--v1","statement":"N-acetylcysteine เป็นยา mucolytic ที่มีฤทธิ์ต้านการอักเสบ ใช้ infuse เข้ามดลูกม้าที่เป็น persistent endometritis","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-23623166","locator":"abstract","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"N-acetylcysteine (NAC), a mucolytic agent with anti-inflammatory properties"}}]},"equine-repro--eqrepro-endometritis--pyometra":{"claims":[{"id":"equine-repro--eqrepro-endometritis--pyometra--v1","statement":"Pyometra ในม้ารักษาแบบ conservative ด้วยการระบายและล้างมดลูก ร่วมกับยาต้านอักเสบและต้านจุลชีพ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31145499","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Conservative therapy consists of draining and flushing the uterus, and systemic anti-inflammatory and antimicrobial treatment."}}]},"equine-repro--eqrepro-endometritis--ป้องกันการกลับเป็นซ้ำ-และงานวิจัยล่าสุด":{"claims":[{"id":"equine-repro--eqrepro-endometritis--ป้องกันการกลับเป็นซ้ำ-และงานวิจัยล่าสุด--v1","statement":"รูปร่าง vulva ที่ผิดปกติเป็นปัจจัยเสี่ยงต่อการติดเชื้อมดลูก และการเย็บปิด vulva (Caslick) ช่วยให้ fertility ดีขึ้น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16268960","locator":"abstract","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Changes in the conformation of the vulva predispose the mare to uterine infection. Vulvoplasty for closure of the upper vulvar lips improves fertility."}}]}},"equine-repro--eqrepro-exam-mare":{"equine-repro--eqrepro-exam-mare--สิ่งที่ตรวจและสิ่งที่คลำไม่ได้ในแม่ม้า":{"claims":[{"id":"equine-repro--eqrepro-exam-mare--สิ่งที่ตรวจและสิ่งที่คลำไม่ได้ในแม่ม้า--v1","statement":"รังไข่ม้าต่างจากสัตว์เลี้ยงลูกด้วยนมอื่นตรงที่มีขนาดใหญ่มาก มี ovarian fossa และมีตำแหน่ง cortex กับ medulla สลับกัน โครงสร้างลูเทียลจึงฝังอยู่ภายในเนื้อรังไข่ และในการศึกษานี้ต้องใช้กล้องจุลทรรศน์โครงสร้างภายในสามมิติจึงจะเห็นและจำแนก corpus haemorrhagicum, corpus luteum และ corpus albicans ได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19469767","locator":"Vol 38(3):214-8, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The structure of the equine ovary is different from that of other mammals in its extremely large size, the presence of ovarian fossa and the inverted location of its cortex and medulla."}},{"id":"equine-repro--eqrepro-exam-mare--สิ่งที่ตรวจและสิ่งที่คลำไม่ได้ในแม่ม้า--v2","statement":"การประเมินระยะวงรอบทางคลินิกอาศัยการล้วงคลำร่วมกับการตรวจ ultrasound ทางทวารหนัก ซึ่งทำให้ตรวจพบการเป็นสัด ฟอลลิเคิลเด่น และ endometrial edema ได้","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-veterinary-manua-2024","locator":"Section on timing of breeding, revised Sept 2024","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The proper time to breed is determined by teasing, palpation, and ultrasonography per rectum, which permits detection of estrus and the presence of a dominant follicle and endometrial edema."}}]},"equine-repro--eqrepro-exam-mare--อ่านระยะวงรอบจาก-ultrasound-uterine-edema":{"claims":[{"id":"equine-repro--eqrepro-exam-mare--อ่านระยะวงรอบจาก-ultrasound-uterine-edema--v1","statement":"ในงานวิจัยทางคลินิก การเป็นสัดถูกนิยามด้วยเกณฑ์ ฟอลลิเคิลบนรังไข่ใหญ่กว่า 3.0 ซม. ร่วมกับการมี endometrial edema ซึ่งตรงกับการใช้ฟอลลิเคิลร่วมกับ edema score อ่านระยะวงรอบตามที่เอกสารสอน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22819282","locator":"Vol 78(6):1199-208, Materials and methods","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Mares (n = 12) were included in the study as soon as estrus was detected (ovarian follicle >3.0 cm and endometrial edema), which was defined as Day 1."}},{"id":"equine-repro--eqrepro-exam-mare--อ่านระยะวงรอบจาก-ultrasound-uterine-edema--v2","statement":"คะแนน endometrial oedema สูงสุดในระยะ oestrus และต่ำกว่าในระยะ dioestrus จึงใช้แยกสองระยะนี้ได้ตามที่เอกสารระบุว่า edema +4 คือ estrus และ edema 0 คือ diestrus","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-41720171","locator":"Vol 160:105815, Results and conclusion","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Image quality was lower ... in images from oestrus compared with dioestrus (2.47 vs 2.67 respectively, p<0.001). Image quality score was negatively associated with oedema scores (p=0002)."}}]},"equine-repro--eqrepro-exam-mare--การซักประวัติก่อนตรวจ-history-taking":{"claims":[{"id":"equine-repro--eqrepro-exam-mare--การซักประวัติก่อนตรวจ-history-taking--v1","statement":"ความสมบูรณ์พันธุ์ของพ่อม้าประเมินด้วย breeding soundness examination ของตัวพ่อม้าเอง ซึ่งอาศัยจำนวนอสุจิ การเคลื่อนที่ รูปร่างที่ปกติ และความสามารถในการผสม จึงเป็นชุดข้อมูลของสัตว์อีกตัวหนึ่ง แยกจากการประเมินแม่ม้า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16054782","locator":"Abstract; 89(1-4):47-56","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"a breeding soundness examination (BSE), based on assessments of sperm number, motility and morphological normality and of mating ability, is often carried out"}}]}},"equine-repro--eqrepro-infertility":{"equine-repro--eqrepro-infertility--pneumovagina-สาเหตุและการแก้ไข":{"claims":[{"id":"equine-repro--eqrepro-infertility--pneumovagina-สาเหตุและการแก้ไข--v1","statement":"โครงสร้างปากช่องคลอดที่ผิดรูปทำให้ม้าเสี่ยงต่อการติดเชื้อในมดลูก และการทำ vulvoplasty ปิดริมฝีปากช่องคลอดส่วนบนซึ่งคือ Caslick's operation ช่วยเพิ่มความสมบูรณ์พันธุ์ ยืนยันว่าการผ่าตัดที่ถูกคือ Caslick ไม่ใช่ Buhner","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16268960","locator":"Vol 52(9):474-7, Abstract opening","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Changes in the conformation of the vulva predispose the mare to uterine infection. Vulvoplasty for closure of the upper vulvar lips improves fertility."}},{"id":"equine-repro--eqrepro-infertility--pneumovagina-สาเหตุและการแก้ไข--v2","statement":"ปากช่องคลอดทำหน้าที่เป็นด่านกั้นเชื้อเข้าสู่ทางเดินสืบพันธุ์ และการแก้ไขโครงสร้างด้วยการผ่าตัดเพื่อให้ปิดสนิทเป็นส่วนหนึ่งของการจัดการ โดยในรายงาน 17 เคส มี 16 ตัวที่ทำหรือขยาย Caslick's operation","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-40607344","locator":"Vol 12:1591452, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"frequently due to bacterial entry via the vulva. The outcome of the pregnancy ... depends on when treatment is initiated, the appropriate medication, and surgical correction of the vulva to ensure an effective seal."}}]},"equine-repro--eqrepro-infertility--post-breeding-endometritis-สู่ภาวะมีบุตรยาก":{"claims":[{"id":"equine-repro--eqrepro-infertility--post-breeding-endometritis-สู่ภาวะมีบุตรยาก--v1","statement":"การปนเปื้อนของมดลูกเกิดจากการปล่อยน้ำเชื้อเข้ามดลูกโดยตรง และหากระบายของเหลวออกไม่ดีหรือการตอบสนองภูมิคุ้มกันไม่เพียงพอ จะกลายเป็น persistent mating-induced endometritis ซึ่งรบกวนการตั้งท้องโดยทำให้สภาพแวดล้อมไม่เหมาะกับการพัฒนาตัวอ่อน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-37191856","locator":"Vol 58 Suppl 2:49-71, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Improper drainage of the ejaculatory fluid or an inadequate immune response may result in persistent mating-induced endometritis."}}]}},"equine-repro--eqrepro-postpartum":{"equine-repro--eqrepro-postpartum--กฎ-1-2-3-ของลูกม้าแรกเกิด":{"claims":[{"id":"equine-repro--eqrepro-postpartum--กฎ-1-2-3-ของลูกม้าแรกเกิด--v1","statement":"ระยะที่สามของการคลอดคือการขับรก ซึ่งต้องเกิดภายใน 3 ชั่วโมง หากค้างนานกว่า 3 ชั่วโมงถือว่าต้องรักษาเพราะเสี่ยง sepsis หรือ laminitis ยืนยันเลข 3 ในส่วนรกของกฎนี้","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-veterinary-manua-2024","locator":"Section on stages of parturition, revised Sept 2024","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Stage 3 is the passage of the fetal membranes, which should occur within a 3-hour period. If the membranes are retained for >3 hours, veterinary treatment is necessary because severe sepsis or laminitis can result."}}]},"equine-repro--eqrepro-postpartum--การดูแลลูกม้าในวันแรกและเกณฑ์ที่ต้องเช็ค":{"claims":[{"id":"equine-repro--eqrepro-postpartum--การดูแลลูกม้าในวันแรกและเกณฑ์ที่ต้องเช็ค--v1","statement":"สายสะดือลูกม้าแรกเกิดควรจุ่มด้วยสารละลายเจือจางของ chlorhexidine 0.5 เปอร์เซ็นต์ หรือ povidone-iodine 1 เปอร์เซ็นต์ วันละหลายครั้ง เป็นเวลา 2 ถึง 3 วัน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-veterinary-manua-2024","locator":"Section on care of the newborn foal, revised Sept 2024","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The newborn foal's umbilicus should be dipped in a dilute solution of chlorhexidine (0.5%) or povidone-iodine (1%) several times a day for 2–3 days."}},{"id":"equine-repro--eqrepro-postpartum--การดูแลลูกม้าในวันแรกและเกณฑ์ที่ต้องเช็ค--v2","statement":"หากระดับ IgG ในซีรัมของลูกม้าต่ำกว่า 800 mg/dL จำเป็นต้องให้พลาสมาทางหลอดเลือดดำ ยืนยันว่าเกณฑ์ผ่านที่เอกสารระบุคือ IgG มากกว่า 800 mg/dL","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-veterinary-manua-2024","locator":"Section on passive transfer of immunity, revised Sept 2024","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"If the foal's serum IgG concentration is < 800 mg/dL, an IV transfusion of plasma is necessary."}},{"id":"equine-repro--eqrepro-postpartum--การดูแลลูกม้าในวันแรกและเกณฑ์ที่ต้องเช็ค--v3","statement":"การประเมินภูมิคุ้มกันรับถ่ายทอดในลูกม้าใช้เกณฑ์ IgG จาก radial immunodiffusion หลายระดับ โดยระดับที่ใช้ประจำคือ น้อยกว่า 400 mg/dL และ น้อยกว่า 800 mg/dL ตรงกับสองตัวเลขที่เอกสารบอกให้แยกให้ออก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-36126780","locator":"Vol 510:113359, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"to estimate RID-IgG of <400 mg/dL, <800 mg/dL, <1500 mg/dL, <2500 mg/dL and < 3000 mg/dL, respectively"}}]},"equine-repro--eqrepro-postpartum--common-neonatal-abnormalities":{"claims":[{"id":"equine-repro--eqrepro-postpartum--common-neonatal-abnormalities--v1","statement":"prematurity หมายถึงลูกม้าที่คลอดเมื่ออายุครรภ์น้อยกว่า 320 วัน ส่วน dysmaturity หมายถึงลูกม้าที่คลอดครบกำหนดแต่แสดงลักษณะแบบคลอดก่อนกำหนด ยืนยันเกณฑ์ 320 วันและการแยกสองคำนี้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-9079128","locator":"Issue 14:3-7, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Prematurity is a term ascribed to foals delivered at less than 320 days gestation whereas dysmaturity, for clinical convenience, describes foals born in the full-term period showing premature-like signs."}},{"id":"equine-repro--eqrepro-postpartum--common-neonatal-abnormalities--v2","statement":"การศึกษาทางคลินิกยุคปัจจุบันยังใช้นิยามเดียวกัน คือวินิจฉัย prematurity เมื่อลูกม้าคลอดก่อนอายุครรภ์ 320 วันร่วมกับลักษณะทางกายภาพที่ยังไม่สมบูรณ์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39547530","locator":"Vol 144:105231, Methods, case definitions","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"prematurity (PRE), when born prior to 320 days of gestation with immature physical characteristics"}},{"id":"equine-repro--eqrepro-postpartum--common-neonatal-abnormalities--v3","statement":"การรักษา meconium impaction ใช้การสวนเป็นหลัก ทั้งสูตรน้ำอุ่นผสมน้ำยาล้างจาน และ acetylcysteine 4 เปอร์เซ็นต์ ที่คาไว้ผ่านสาย Foley นาน 30 ถึง 45 นาที ยืนยันทั้งน้ำสบู่และ acetylcysteine ที่เอกสารระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-veterinary-manua-2024","locator":"Treatment section, revised Sept 2024","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Warm-water liquid detergent enemas (½ teaspoon liquid detergent added to 500 mL water)"}},{"id":"equine-repro--eqrepro-postpartum--common-neonatal-abnormalities--v4","statement":"ในการตรวจ ณ จุดดูแลผู้ป่วย เกณฑ์ IgG น้อยกว่า 400 mg/dL ถูกใช้เป็นระดับวินิจฉัย failure of transfer of passive immunity โดยชุดตรวจให้ความไวร้อยละ 94 และความจำเพาะร้อยละ 100 ที่ระดับนี้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28561898","locator":"Vol 31(4):1170-1177, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Sensitivity and specificity at optimal cutoff were 94 and 100% for the POC-TIA and 94 and 100% for the POC-ELISA to detect IgG <400 mg/dL"}}]},"equine-repro--eqrepro-postpartum--neonatal-isoerythrolysis-ni":{"claims":[{"id":"equine-repro--eqrepro-postpartum--neonatal-isoerythrolysis-ni--v1","statement":"ภาวะ alloimmune ในลูกม้าเกิดเมื่อแม่ม้าสร้างแอนติบอดีต่อแอนติเจนบนเซลล์ของลูก แล้วสะสมไว้ในนมน้ำเหลือง เมื่อลูกดูดและดูดซึมแอนติบอดีจากนมน้ำเหลืองจึงเกิด neonatal isoerythrolysis ซึ่งเป็นภาวะเม็ดเลือดแดงแตกจากแอนติบอดีที่จำเพาะต่อแฟกเตอร์บนเม็ดเลือดแดงของลูก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38852013","locator":"Vol 40(2):189-206, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Alloimmune disorders occur in foals when pregnant mares produce antibodies against antigens on the foal's cells or tissues, and concentrate them within colostrum. Once foals nurse and absorb colostral antibodies, they can develop hematologi"}},{"id":"equine-repro--eqrepro-postpartum--neonatal-isoerythrolysis-ni--v2","statement":"IgG ของแม่ม้าไม่ผ่านรก การถ่ายทอดภูมิคุ้มกันจึงต้องเกิดหลังคลอดผ่านนมน้ำเหลือง ซึ่งอธิบายว่าทำไมปัญหา NI จึงเกิดหลังลูกกินนมมื้อแรกไม่ใช่ขณะอยู่ในท้อง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-9079128","locator":"Issue 14:3-7, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Maternal IgG does not cross the placental barrier and passive transfer post-natally is essential for immune status."}},{"id":"equine-repro--eqrepro-postpartum--neonatal-isoerythrolysis-ni--v3","statement":"ในพื้นที่ที่มี equine piroplasmosis ชุกชุม ภาวะดีซ่านรุนแรงในลูกม้าหลังคลอดถูกวินิจฉัยผิดเป็น neonatal isoerythrolysis ได้ง่าย จึงควรตรวจหา Theileria equi ร่วมด้วยก่อนสรุปว่าเป็น NI","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-21051152","locator":"Vol 175(3-4):363-6, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In areas where equine piroplasmosis is endemic, severe jaundice in a post-partum foal may be easily misdiagnosed as neonatal isoerythrolysis."}}]},"equine-repro--eqrepro-postpartum--post-partum-breeding-และ-foal-heat":{"claims":[{"id":"equine-repro--eqrepro-postpartum--post-partum-breeding-และ-foal-heat--v1","statement":"แม่ม้าหลังคลอดกลับเป็นสัดเร็ว โดยในการศึกษาย้อนหลัง 694 mare-years พบว่า 92.94% แสดงอาการเป็นสัดภายใน 21 วันหลังคลอด และ foal heat (เป็นสัดร่วมกับยืนยันการตกไข่) เริ่มที่ 8.42 ± 0.17 วัน ส่วนการตกไข่ครั้งแรกที่ 13.64 ± 0.20 วันหลังคลอด ซึ่งครอบคลุมช่วง 10-15 วันตามที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20207409","locator":"Abstract, Results (vol 74, issue 1, pp 90-99)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Overt oestrous activity occurred within 21 d postpartum in 92.94% (645/694) of mares... onset of FH (oestrus plus confirmed ovulation) occurred 8.42+/-0.17 d and first ovulation 13.64+/-0.20 d postpartum."}}]},"equine-repro--eqrepro-postpartum--ภาวะผิดปกติของแม่ม้าหลังคลอด":{"claims":[{"id":"equine-repro--eqrepro-postpartum--ภาวะผิดปกติของแม่ม้าหลังคลอด--v1","statement":"นิยามของ retained placenta ในม้าคือการที่เยื่อหุ้มลูกไม่ถูกขับออกครบภายใน 3 ชั่วโมงหลังลูกม้าคลอด ซึ่งตรงกับเกณฑ์ 3 ชั่วโมงในสไลด์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-14757471","locator":"Materials and methods, case definition (vol 61, issue 5, pp 851-859)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Retained placenta was defined as a failure to expel all fetal membranes within 3 h of the delivery of the foal."}},{"id":"equine-repro--eqrepro-postpartum--ภาวะผิดปกติของแม่ม้าหลังคลอด--v2","statement":"การรักษารกค้างด้วย oxytocin ทางหลอดเลือดดำร่วมกับการล้างมดลูก (uterine lavage) ได้ผลใน 65% ของแม่ม้า และรกค้างสัมพันธ์กับ postpartum metritis อย่างชัดเจน โดยพบ metritis 59% ในกลุ่มรกค้าง เทียบกับ 7% ในกลุ่มควบคุม นอกจากนี้รกค้างพบบ่อยกว่าหลัง dystocia (38% เทียบกับ 12% หลังคลอดปกติ)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-42208779","locator":"Abstract, Results (vol 165, article 105946)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Postpartum metritis was significantly more frequent in the R group (32/54, 59%) compared with the C group (7/267, 7%) (p < 0.00001)... Sixty-five percent of mares were successfully treated with IV oxytocin and uterine lavages."}}]},"equine-repro--eqrepro-postpartum--พฤติกรรมลูกม้าและ-imprinting":{"claims":[{"id":"equine-repro--eqrepro-postpartum--พฤติกรรมลูกม้าและ-imprinting--v1","statement":"การทำ imprint training ตั้งแต่แรกเกิดและซ้ำที่อายุ 24 ชั่วโมง ทำให้ลูกม้าต้านการจับขาหน้า ขาหลัง และการยกเท้าหลังน้อยลงอย่างมีนัยสำคัญเมื่ออายุ 3 เดือน จึงสนับสนุนว่าการทำความคุ้นเคยในช่วงวันแรก ๆ ให้ผลจริง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15501142","locator":"Results; 168(3):252-8","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Conditioned foals (Group A) were significantly less resistant to touching the front and hind legs and picking up the hind feet (P < 0.05)."}}]},"equine-repro--eqrepro-postpartum--ลูกม้ากำพร้าแม่":{"claims":[{"id":"equine-repro--eqrepro-postpartum--ลูกม้ากำพร้าแม่--v1","statement":"ความจุกระเพาะของลูกม้าเป็นตัวจำกัดปริมาณนมต่อมื้อและปริมาณ milk replacer ที่กินได้ จึงต้องป้อนทีละน้อยและถี่ และการป้อนปริมาณสูงเกินไปทำให้ท้องเสียเกิดเร็วขึ้นและนานขึ้น (6.3 วัน เทียบกับ 2.5-3.6 วัน)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17424268","locator":"Results and Discussion; 34(8):479-86","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The foal's stomach capacity appears to limit meal size and thus replacer intake."}},{"id":"equine-repro--eqrepro-postpartum--ลูกม้ากำพร้าแม่--v2","statement":"มีรายงานแม่ม้าลาย (plains zebra, Equus burchellii) ที่กำลังให้นมรับเลี้ยงลูกกำพร้าและให้นมลูก 2 ตัวพร้อมกันได้เป็นประจำ แต่แม่ที่เลี้ยง 2 ตัวปฏิเสธการดูดนมบ่อยกว่าและช่วงดูดนมสั้นกว่าแม่ตัวอื่น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-21126562","locator":"Abstract; 86(2):174-7","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"We observed a case of adoption of an orphaned foal by a lactating mare, who then regularly nursed two foals (filial and non-filial)."}}]},"equine-repro--eqrepro-postpartum--post-parturition-check-ของแม่ม้า":{"claims":[{"id":"equine-repro--eqrepro-postpartum--post-parturition-check-ของแม่ม้า--v1","statement":"รกค้าง (retained fetal membranes) เป็นภาวะหลังคลอดที่พบบ่อยที่สุดในแม่ม้า จึงต้องตรวจว่ารกออกครบ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31279434","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Retained fetal membranes are the most common postpartum condition in mares. Although the incidence of retained fetal membranes is low, the consequences for the health of the mare can be severe"}}]},"equine-repro--eqrepro-postpartum--intrapartum-conditions-1-red-bag-abortion-และ-uterine-inertia":{"claims":[{"id":"equine-repro--eqrepro-postpartum--intrapartum-conditions-1-red-bag-abortion-และ-uterine-inertia--v1","statement":"premature placental separation ของ chorioallantois เป็นปัจจัยเสี่ยงสำคัญของภาวะขาดออกซิเจนในลูกม้า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35622344","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Equine premature placental separation (PPS) is poorly understood and represents an important risk factor for fetal/neonatal hypoxia."}}]},"equine-repro--eqrepro-postpartum--intrapartum-conditions-2-premature-mammary-development-placental":{"claims":[{"id":"equine-repro--eqrepro-postpartum--intrapartum-conditions-2-premature-mammary-development-placental--v1","statement":"ในม้าที่เกิด placentitis จากการทดลอง การให้ trimethoprim sulfamethoxazole, pentoxifylline และ altrenogest (progestin) ทำให้คลอดลูกมีชีวิต 83% เทียบกับ 0% ในกลุ่มไม่รักษา","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20416936","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"More mares in Group TREAT delivered viable foals (10/12; 83%; P < 0.05) than mares in Group UNTREAT (0/5; 0%)."}}]},"equine-repro--eqrepro-postpartum--intrapartum-conditions-3-uterine-torsion-retained-fetal-membrane":{"claims":[{"id":"equine-repro--eqrepro-postpartum--intrapartum-conditions-3-uterine-torsion-retained-fetal-membrane--v1","statement":"uterine torsion เป็นภาวะแทรกซ้อน 5-10% ของช่วง trimester สุดท้ายในม้า และแก้ด้วยการผ่าตัดเปิดสีข้างหรือ midline","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-40993602","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Uterine torsion in mares belongs to maternal pregnancy disorders, accounting for 5-10% of complications in the last trimester of pregnancy. Two surgical techniques for repositioning uterine torsion are used"}}]},"equine-repro--eqrepro-postpartum--dystocia":{"claims":[{"id":"equine-repro--eqrepro-postpartum--dystocia--v1","statement":"Dystocia พบ 10.1% ของการคลอดในงานศึกษา 1047 ราย และสาเหตุที่พบบ่อยที่สุดคือความผิดปกติของ posture ลูก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22594021","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Dystocia occurred in 10.1% of all births... The most common cause of dystocia was abnormalities of fetal posture."}}]},"equine-repro--eqrepro-postpartum--post-partum-breeding-foal-heat":{"claims":[{"id":"equine-repro--eqrepro-postpartum--post-partum-breeding-foal-heat--v1","statement":"Pregnancy rate ของแม่ม้าที่ผสมที่ foal heat ต่ำกว่าที่ผสมที่ heat ครั้งที่สอง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32534765","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"PregR in mares bred on FH was lower compared with SH (P < .01)"}}]}},"equine-repro--eqrepro-pregnancy":{"equine-repro--eqrepro-pregnancy--ตัวเลขหลักที่ต้องจำ":{"claims":[{"id":"equine-repro--eqrepro-pregnancy--ตัวเลขหลักที่ต้องจำ--v1","statement":"ระยะตั้งท้องเฉลี่ยของม้าจากการเก็บบันทึกการคลอด 1,047 ครั้งคือ 342.7 ± 0.4 วัน โดยไม่พบผลของอายุหรือสายพันธุ์ของแม่ม้า แต่แม่ม้าที่อุ้มลูกเพศผู้ท้องนานกว่าเพศเมียอย่างมีนัยสำคัญ ตัวเลขนี้สอดคล้องกับ 340 วันในสไลด์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22594021","locator":"Abstract, Results (issue 41, pp 22-25)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The average gestation length was 342.7 days +/- 0.4 days, with no effect of mare age or breed observed. Mares carrying male fetuses had a longer gestation (P < or = 0.001) than mares carrying female fetuses."}}]},"equine-repro--eqrepro-pregnancy--early-pregnancy-จาก-oviduct-ถึง-fixation":{"claims":[{"id":"equine-repro--eqrepro-pregnancy--early-pregnancy-จาก-oviduct-ถึง-fixation--v1","statement":"การขนส่งตัวอ่อนผ่าน uterotubal junction (UTJ) จาก oviduct เข้าสู่มดลูกเป็นการคัดเลือกเฉพาะตัวอ่อน และถูกขับเคลื่อนด้วย PGE2 ที่สร้างจากตัวอ่อนเอง ตรงกับกลไกที่สไลด์ระบุ นอกจากนี้ยังเกิด acellular glycoprotein capsule ห่อตัวอ่อนในสัปดาห์ที่ 2-3 ของการตั้งท้อง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26450499","locator":"Abstract, opening paragraph (vol 216, pp 165-188)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Following fertilization and initial development in the mare oviduct, selective transport of the embryo through the uterotubal junction driven by embryo-derived PGE2 occurs."}},{"id":"equine-repro--eqrepro-pregnancy--early-pregnancy-จาก-oviduct-ถึง-fixation--v2","statement":"ตัวอ่อนม้าเคลื่อนที่ (embryo mobility) ได้สูงสุดในวันที่ 12-15 หลังตกไข่ ขณะที่ตัวอ่อนทรงกลมโตจาก 9 เป็น 23 มม. และหยุดเคลื่อนที่ (fixation) ประมาณวันที่ 16 ที่รอยโค้งของ uterine horn ซึ่งมีเส้นผ่านศูนย์กลาง endometrium ใกล้เคียงกับขนาดตัวอ่อน สอดคล้องกับช่วง migration และ fixation ในสไลด์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34670705","locator":"Abstract (vol 106, article 103747)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Embryo mobility is maximum on Days 12 to 15 (Day 0 = ovulation) while the spherical embryo is growing from 9 to 23 mm in diameter... Fixation occurs on ~ Day 16 at a bend or flexure in a uterine horn."}},{"id":"equine-repro--eqrepro-pregnancy--early-pregnancy-จาก-oviduct-ถึง-fixation--v3","statement":"capsule ที่เป็นไกลโคโปรตีนเหนียวยืดหยุ่นหุ้ม equine blastocyst ตั้งแต่วันที่ 6 ถึงวันที่ 23 หลังตกไข่ และตัวอ่อนเดินทางทั่ว uterine lumen ในวันที่ 6-17 โดยถูกขับเคลื่อนด้วยการบีบตัวของ myometrium ที่กระตุ้นด้วยการหลั่ง PGF2alpha และ PGE2 แบบเป็นจังหวะ ยืนยันว่าตัวอ่อนที่ลงมาถึงมดลูกอยู่ในระยะ blastocyst ประมาณวันที่ 6 ตามที่สไลด์ทำเครื่องหมายว่าเป็นจุดออกข้อสอบ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-11999314","locator":"Abstract, first paragraph (vol 13, issue 7-8, pp 623-634)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A tough, elastic glycoprotein capsule envelops the equine blastocyst between Days 6 and 23 after ovulation... as the embryo traverses the entire uterine lumen during Days 6-17, propelled by myometrial contractions that are stimulated by pul"}}]},"equine-repro--eqrepro-pregnancy--maternal-recognition-of-pregnancy":{"claims":[{"id":"equine-repro--eqrepro-pregnancy--maternal-recognition-of-pregnancy--v1","statement":"สัญญาณ maternal recognition of pregnancy ในม้ายังไม่มีการระบุตัวได้ชัดเจน โดยการทดลองที่พยายามพิสูจน์ว่า estrogen จากตัวอ่อนเป็นตัวยืดอายุ corpus luteum ให้ผลไม่สรุป ส่วนกลไกที่ยืนยันได้คือการลดการหลั่ง PGF2alpha จาก endometrium ผ่านการลด expression ของเอนไซม์สังเคราะห์ prostaglandin และการลด oxytocin receptor ตรงกับที่สไลด์บอกว่าสารตัวนี้ยังไม่ทราบชื่อ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26450499","locator":"Abstract, maternal recognition section (vol 216, pp 165-188)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"During maternal recognition of pregnancy, endometrial PGF2alpha release is attenuated, a consequence of reduced expression of key enzymes involved in prostaglandin production... Results of experiments attempting to prove that conceptus-deri"}}]},"equine-repro--eqrepro-pregnancy--mid-pregnancy-40-180-วัน-endometrial-cup-ecg-และ-accessory-cl":{"claims":[{"id":"equine-repro--eqrepro-pregnancy--mid-pregnancy-40-180-วัน-endometrial-cup-ecg-และ-accessory-cl--v1","statement":"ที่วันที่ 35 trophoblast แยกเป็นส่วน invasive และ non-invasive โดยส่วน invasive คือ chorionic girdle ที่หนาเป็นวงแหวน จะรุกเข้า endometrium ของแม่เพื่อสร้าง endometrial cup ซึ่งหลั่ง chorionic gonadotrophin ไปเหนี่ยวนำให้เกิด secondary luteal development ในรังไข่ของแม่ ตรงกับกลไก endometrial cup กับ accessory CL ในสไลด์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-11999314","locator":"Abstract (vol 13, issue 7-8, pp 623-634)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"At Day 35, the trophoblast of the spherical conceptus has separated into its invasive and non-invasive components. The former, distinguished as the thickened, annulate chorionic girdle, invades the maternal endometrium to form the unique en"}},{"id":"equine-repro--eqrepro-pregnancy--mid-pregnancy-40-180-วัน-endometrial-cup-ecg-และ-accessory-cl--v2","statement":"eCG มีฤทธิ์แบบ luteinizing hormone (LH) ในม้า ทำให้ follicle เกิด luteinization กลายเป็น secondary corpora lutea ซึ่งจำเป็นต่อการสร้าง progesterone และการคงการตั้งท้อง ตรงกับที่สไลด์ระบุว่า eCG ทำงานคล้าย LH และให้ accessory CL ที่สร้าง P4","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26450499","locator":"Abstract, final sentence (vol 216, pp 165-188)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Equine chorionic gonadotropin has luteinizing hormone functions in the mare, causing luteinization of follicles resulting in the formation of secondary corpora lutea essential to production of progesterone and maintenance of pregnancy."}},{"id":"equine-repro--eqrepro-pregnancy--mid-pregnancy-40-180-วัน-endometrial-cup-ecg-และ-accessory-cl--v3","statement":"endometrial cup สร้างขึ้นในวันที่ 35-40 ของการตั้งท้อง และมีผลทางคลินิกสำคัญคือ ถ้าแม่ม้าแท้งหลังจากที่ endometrial cup ตั้งตัวแล้ว แม่ม้ามักไม่กลับเป็นสัดอีกหลายเดือน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-3044536","locator":"Reproductive Physiology, point 6 (vol 4, issue 2, pp 215-220)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"After the establishment of endometrial cups (Days 35 to 40), mares that are aborted will frequently not cycle for several months."}}]},"equine-repro--eqrepro-pregnancy--late-pregnancy":{"claims":[{"id":"equine-repro--eqrepro-pregnancy--late-pregnancy--v1","statement":"รกม้าสร้าง progesterone และ 5alpha-reduced progestagens เอง โดยอาศัย pregnenolone จากต่อมหมวกไตทั้งของแม่และของลูก ส่วน oestrogen ที่สูงมากในเลือดและปัสสาวะแม่ม้าช่วงครึ่งหลังของการตั้งท้อง เกิดจากรก aromatize สาร C-19 precursor ที่หลั่งจาก fetal gonad ที่โตขึ้นชั่วคราว ตรงกับกราฟในสไลด์ที่ oestrogen จาก foetal gonad ขึ้นช่วงท้าย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-11999314","locator":"Abstract, final two sentences (vol 13, issue 7-8, pp 623-634)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the high concentrations of conventional and unique ring B unsaturated oestrogens in the blood and urine of mares during the second half of pregnancy stem from placental aromatization of large quantities of C-19 precursor molecules secreted "}}]},"equine-repro--eqrepro-pregnancy--ตารางตรวจ-ultrasound-4-รอบ":{"claims":[{"id":"equine-repro--eqrepro-pregnancy--ตารางตรวจ-ultrasound-4-รอบ--v1","statement":"การจัดการลูกแฝดทำได้โดยการบี้ถุงตัวอ่อนหนึ่งใบด้วยนิ้วมือหรือด้วยหัวตรวจ ultrasound ในขณะที่ตัวอ่อนยังเคลื่อนที่ได้หรือเมื่อ fixation แบบ bilateral ตรงกับที่สไลด์ระบุว่าต้องบี้ทิ้งถุงหนึ่ง นอกจากนี้ยังพบว่า unilateral fixation ของแฝดสัมพันธ์กับ natural embryo reduction ในอัตราสูง (เช่น 85%) ขณะที่ bilateral fixation ทำให้ natural reduction เกิดไม่ได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34670705","locator":"Abstract, final sentences (vol 106, article 103747)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Unilateral fixation of twins is associated with a high frequency (e.g., 85%) of natural embryo reduction... whereas bilateral fixation precludes natural embryo reduction. The theriogenologist can efficiently solve the twinning problem by co"}},{"id":"equine-repro--eqrepro-pregnancy--ตารางตรวจ-ultrasound-4-รอบ--v2","statement":"การดูเพศลูกม้าด้วย ultrasound แบบระยะแรกทำที่อายุครรภ์ประมาณวันที่ 58-70 โดยอาศัยตำแหน่งของ genital tubercle ตรงกับสไลด์ที่ระบุว่าดูเพศได้ตั้งแต่วันที่ 60 ขึ้นไป และยังมีหน้าต่างที่สองที่กว้างกว่าคือวันที่ 120-210 ซึ่งดูจากอวัยวะสืบพันธุ์ที่พัฒนาเต็มที่","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15993481","locator":"Abstract (vol 64, issue 3, pp 568-571)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Early equine fetal sexing techniques, performed between approximately Days 58 and 70, are aimed at identifying the position of the genital tubercle."}},{"id":"equine-repro--eqrepro-pregnancy--ตารางตรวจ-ultrasound-4-รอบ--v3","statement":"เหตุผลที่ต้องเร่งตรวจหาลูกแฝดตั้งแต่ระยะแรกคือการตั้งท้องแฝดในม้าทำให้เกิดการแท้ง การคลอดลูกตาย และการตายในระยะแรกเกิดในอัตราสูง ตรงกับที่สไลด์ระบุว่าแฝดในม้ามักแท้งระยะท้าย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-3044536","locator":"Reproductive Physiology, point 1 (vol 4, issue 2, pp 215-220)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Twin pregnancies result in high rates of abortion, stillbirth, and neonatal mortality."}}]},"equine-repro--eqrepro-pregnancy--1-เดือนก่อนคลอด":{"claims":[{"id":"equine-repro--eqrepro-pregnancy--1-เดือนก่อนคลอด--v1","statement":"แคลเซียมในน้ำนมก่อนคลอดสูงขึ้นเมื่อใกล้คลอดและใช้ทำนายการคลอดได้ โดยเมื่อ calcium carbonate ในน้ำนมเจือจางถึงระดับ 200 ppm ขึ้นไป มีแม่ม้า 51.4% คลอดภายใน 24 ชั่วโมง 84.1% ภายใน 48 ชั่วโมง และ 97.2% ภายใน 72 ชั่วโมง ส่วนค่าต่ำกว่า 200 ppm ทำนายว่า 99.6% จะไม่คลอดใน 24 ชั่วโมงถัดไป ตรงกับหลักการ strip test ในสไลด์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16727305","locator":"Abstract, Results (vol 40, issue 1, pp 189-198)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The predictive value of a positive test (PVPT; positive test defined as the first occurrence that prefoaling mammary secretion calcium carbonate >/= 200 ppm) indicated that 51.4% of late term pregnant mares would foal within the ensuing 24-"}},{"id":"equine-repro--eqrepro-pregnancy--1-เดือนก่อนคลอด--v2","statement":"ลูกม้าแรกเกิดดูดซึม immunoglobulin จากนมน้ำเหลืองที่ลำไส้เล็กได้สูงสุดถึงประมาณ 8 ชั่วโมงหลังคลอด แล้วลดลงเรื่อยๆ จนเป็นศูนย์หลัง 24 ชั่วโมง ซึ่งเป็นเหตุผลของกฎ 24 ชั่วโมงแรกในสไลด์ และค่า cut-off ของ failure of passive transfer คือ serum immunoglobulin 8 g/L","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31975477","locator":"Abstract, Background and Results (vol 52, issue 5, pp 760-764)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In newborn foals the absorption of colostrum immunoglobulins in the small intestine is maximal up to 8 hours after birth and then progressively decreases to become null after 24 hours post-partum."}},{"id":"equine-repro--eqrepro-pregnancy--1-เดือนก่อนคลอด--v3","statement":"รกม้าเป็นชนิด diffuse epitheliochorial ที่ trophoblast ส่วน non-invasive ของ allantochorion สร้าง microvillous contact กับ endometrial epithelium ราววันที่ 40 แล้วพัฒนาเป็น microcotyledonary exchange unit โครงสร้างที่ชั้นเยื่อบุแม่ยังคงอยู่ครบนี้คือพื้นฐานทางกายวิภาคที่ทำให้ลูกม้าต้องพึ่งนมน้ำเหลืองแทนการรับภูมิผ่านรก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-11999314","locator":"Abstract (vol 13, issue 7-8, pp 623-634)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The non-invasive trophoblast of the allantochorion establishes a stable microvillous contact with the endometrial epithelium around Day 40 and, over the next 100 days, develops a complex multibranched interdigitation with the endometrium to"}}]},"equine-repro--eqrepro-pregnancy--routine-care-และวัคซีนแม่ม้าท้อง":{"claims":[{"id":"equine-repro--eqrepro-pregnancy--routine-care-และวัคซีนแม่ม้าท้อง--v1","statement":"แนวปฏิบัติของ AAEP ระบุให้ฉีดวัคซีน EHV-1 ชนิดเชื้อตายที่ขึ้นทะเบียนสำหรับป้องกันการแท้ง ในเดือนที่ 5, 7 และ 9 ของการตั้งท้อง ตรงกับตารางในสไลด์ (เฉพาะส่วน EHV-1)","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-american-association-o-2025","locator":"Vaccination Schedules, subsection 'Pregnant mares', page 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Pregnant mares: Vaccinate during the fifth, seventh, and ninth months of gestation using an inactivated EHV-1 vaccine licensed for prevention of abortion."}},{"id":"equine-repro--eqrepro-pregnancy--routine-care-และวัคซีนแม่ม้าท้อง--v2","statement":"วัคซีนกลุ่ม core ของแม่ม้าท้อง ได้แก่ tetanus, EEE/WEE, West Nile virus และ rabies ให้ฉีดปีละครั้งที่ 4-6 สัปดาห์ก่อนคลอด (rabies เลือกได้ระหว่าง 4-6 สัปดาห์ก่อนคลอด หรือก่อนผสม) ใกล้เคียงกับ 1 เดือนก่อนคลอดในสไลด์ โดยหน้าต่างที่แนะนำจริงคือ 4-6 สัปดาห์ และเหตุผลของช่วงเวลานี้คือเพื่อเพิ่มระดับ immunoglobulin ในนมน้ำเหลืองสำหรับส่งต่อให้ลูก","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-american-association-o-2026","locator":"Core Vaccinations table, Broodmares column, rows EEE/WEE, Rabies, Tetanus, West Nile Virus","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Eastern / Western Equine Encephalomyelitis (EEE/WEE), Broodmares, Previously vaccinated: Annual, 4 to 6 weeks prepartum... Rabies: Annual, 4 to 6 weeks prepartum OR Prior to breeding... Tetanus: Annual, 4 to 6 weeks prepartum... West Nile V"}}]},"equine-repro--eqrepro-pregnancy--3-stages-of-parturition":{"claims":[{"id":"equine-repro--eqrepro-pregnancy--3-stages-of-parturition--v1","statement":"แม่ม้าส่วนใหญ่คลอดกลางคืน โดยในบันทึกการคลอด 1,047 ครั้ง มี 52.8% คลอดระหว่างเวลา 20.00 ถึง 02.00 น. ซึ่งเป็นช่วงที่สถานที่เงียบสงบ ตรงกับที่สไลด์ระบุว่าม้ามักคลอดกลางคืน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22594021","locator":"Abstract, Results (issue 41, pp 22-25)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A majority (52.8%) of mares foaled at night between 2000 h and 0200 h when the facility was quiet."}},{"id":"equine-repro--eqrepro-pregnancy--3-stages-of-parturition--v2","statement":"ระยะเวลาเฉลี่ยของ stage II ในการคลอดปกติที่มีผู้ดูแลของแม่ม้า Thoroughbred สุขภาพดี คือ 17.3 ± 5.1 นาที ซึ่งอยู่ในช่วง 5-30 นาทีตามที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-29859395","locator":"Abstract, Results (vol 118, pp 1-6)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The mean time for stage 2 labour and blood gas analysis after parturition was 17.3 +/- 5.1 min and 5.0 +/- 2.3 min, respectively."}},{"id":"equine-repro--eqrepro-pregnancy--3-stages-of-parturition--v3","statement":"เกณฑ์ของ stage III คือรกต้องถูกขับออกให้ครบ ถ้าเกิน 3 ชั่วโมงหลังลูกม้าคลอดถือเป็น retained placenta ตรงกับนิยามที่ใช้ในงานวิจัยทางคลินิก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-14757471","locator":"Materials and methods, case definition (vol 61, issue 5, pp 851-859)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Retained placenta was defined as a failure to expel all fetal membranes within 3 h of the delivery of the foal."}}]},"equine-repro--eqrepro-pregnancy--intrapartum-conditions-ที่ต้องรู้จัก":{"claims":[{"id":"equine-repro--eqrepro-pregnancy--intrapartum-conditions-ที่ต้องรู้จัก--v1","statement":"การให้ oxytocin เจือจางใน 0.9% NaCl 1 ลิตร หยดเข้าหลอดเลือดดำ เป็นเทคนิคที่มีการศึกษาเปรียบเทียบจริงในม้า และให้ช่วงเวลาจากการให้ยาถึงการแตกของ chorioallantois สั้นกว่าการฉีดเข้ากล้ามเป็นครั้งๆ อย่างไรก็ตามขนาดยาในงานวิจัยนี้คือ 75 IU ใน 1 ลิตร ให้ที่อัตรา 1 IU ต่อนาที ซึ่งสูงกว่าขนาด 5-15 IU ที่สไลด์ระบุ (งานวิจัยนี้เป็นการเหนี่ยวนำการคลอด ไม่ใช่การแก้ uterine inertia โดยตรง)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-9074683","locator":"Abstract, Procedure and Results (vol 210, issue 6, pp 799-803)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"group 3, 75 U of oxytocin in 1 L of 0.9% NaCl solution IV (1 U/min)... Group-3 mares had a shorter interval from administration of oxytocin to rupture of the chorioallantois (OTCA) than group-2 mares."}},{"id":"equine-repro--eqrepro-pregnancy--intrapartum-conditions-ที่ต้องรู้จัก--v2","statement":"uterine torsion ในม้ามักเกิดช่วงท้ายของการตั้งท้อง โดยค่าเฉลี่ยอายุครรภ์ตอนวินิจฉัยคือ 283 วัน (ช่วง 153-369 วัน) และการรักษาคือการผ่าตัด โดย standing flank laparotomy เป็นวิธีที่เลือกใช้เป็นอันดับแรกสำหรับ uterine torsion ที่ไม่ซับซ้อน ยกเว้นเมื่ออายุครรภ์เกิน 320 วัน หลังแก้ไขแล้วแม่ม้ารอด 90.5% และลูกม้ารอด 82.3%","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25640418","locator":"Abstract, Results and Conclusions (vol 48, issue 2, pp 172-175)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Mean stage of gestation at diagnosis was 283 days (range 153-369 days)... After correction of UT, 90.5% of mares and 82.3% of foals survived to hospital discharge... Standing flank laparotomy is the surgical technique of choice for resolvin"}},{"id":"equine-repro--eqrepro-pregnancy--intrapartum-conditions-ที่ต้องรู้จัก--v3","statement":"การใช้ ultrasound ประเมิน combined thickness of the uterus and placenta (CTUP) ที่หนาขึ้น ร่วมกับภาพการลอกตัวของรก เป็นเครื่องมือตรวจจับ placentitis และการตั้งท้องผิดปกติ โดยพบค่า CTUP สูงกว่า 75th percentile ของกลุ่มปกติใน 100% ของกลุ่ม placentitis และ 86% ของกลุ่มที่คลอดผิดปกติ สนับสนุนหลักการ 'ตรวจต่อด้วย ultrasound จะเห็นรกหนา' ในสไลด์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-29593442","locator":"Abstract, Results (vol 29, issue 1, pp 1-8)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Values of CTUP greater than the 75th percentile of the normal group from Months 7 (7.54 mm) to 12 (15.19 mm) were detected in 100% of the placentitis group (3/3) and in 86% of the abnormal group (6/7)."}}]},"equine-repro--eqrepro-pregnancy--red-bag-premature-separation-of-the-placenta":{"claims":[{"id":"equine-repro--eqrepro-pregnancy--red-bag-premature-separation-of-the-placenta--v1","statement":"equine premature placental separation (PPS หรือ red bag) เป็นปัจจัยเสี่ยงสำคัญของภาวะขาดออกซิเจนในลูกม้าทั้งระยะ fetal และ neonatal และพยาธิสภาพของ chorioallantois อยู่บริเวณใกล้ cervical star ซึ่งเป็นตำแหน่งที่ปกติเยื่อหุ้มต้องแตกออก ตรงกับกลไกในสไลด์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35622344","locator":"Abstract, Background and Methods (vol 55, issue 3, pp 405-418)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Equine premature placental separation (PPS) is poorly understood and represents an important risk factor for fetal/neonatal hypoxia... Transcriptomic changes in the villous CA near the cervical star were determined."}},{"id":"equine-repro--eqrepro-pregnancy--red-bag-premature-separation-of-the-placenta--v2","statement":"ลูกม้าที่เกิดหลัง premature placental separation มีหลักฐานทางคลินิกของภาวะขาดออกซิเจน โดยลูกม้าที่มีประวัติ dystocia หรือ premature placental separation มีระดับ L-lactate ตอนรับเข้าโรงพยาบาลสูงขึ้นอย่างมีนัยสำคัญ และค่า L-lactate ที่สูงขึ้นทุก 1 mmol/L เพิ่ม odds ของการไม่รอดชีวิต สนับสนุนความจำเป็นที่ต้องรีบฉีกถุงและช่วยคลอดทันที","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22594028","locator":"Abstract, Results (issue 41, pp 57-63)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Foals experiencing known dystocia or premature placental separation had increased [LAC]ADMIT (P < 0.001)."}}]},"equine-repro--eqrepro-pregnancy--dystocia-ในม้า":{"claims":[{"id":"equine-repro--eqrepro-pregnancy--dystocia-ในม้า--v1","statement":"จากบันทึกการคลอด 1,047 ครั้ง พบ dystocia 10.1% และสาเหตุที่พบบ่อยที่สุดคือความผิดปกติของท่าลูก (abnormalities of fetal posture) โดยพบอัตราสูงกว่าใน Thoroughbred เทียบกับ Quarter Horse ตรงกับที่สไลด์ระบุว่า dystocia ในม้ามักเกิดจากท่าผิดปกติ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22594021","locator":"Abstract, Results (issue 41, pp 22-25)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Dystocia occurred in 10.1% of all births and the incidence rate was higher in Thoroughbred mares than in Quarter Horse mares. The most common cause of dystocia was abnormalities of fetal posture."}},{"id":"equine-repro--eqrepro-pregnancy--dystocia-ในม้า--v2","statement":"ในเคส dystocia ที่รุนแรงจนต้องทำ fetotomy จำนวน 102 ตัว ท่าผิดปกติที่พบบ่อยที่สุดคือ head malposture (62.7%) ซึ่งเป็นหลักฐานเพิ่มเติมว่า malposition/malposture เป็นสาเหตุหลักของ dystocia ในม้า ไม่ใช่ขนาดลูกที่ใหญ่เกิน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24570408","locator":"Abstract, Results (vol 174, issue 16, p 407)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Head malposture (62.7 per cent) was the most common fetal maldisposition, which required fetotomy in all cases."}}]},"equine-repro--eqrepro-pregnancy--early-pregnancy-0-40-วัน-oviductal-transportation-และ-pge2":{"claims":[{"id":"equine-repro--eqrepro-pregnancy--early-pregnancy-0-40-วัน-oviductal-transportation-และ-pge2--v1","statement":"ตัวอ่อนม้าเข้า uterus ที่ราว 144-156 ชั่วโมงหลัง ovulation โดย PGE2 จากตัวอ่อนช่วยคลายกล้ามเนื้อเรียบของ isthmus","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20681173","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Equine embryos enter the uterus 144-156 h after ovulation... further onward movement of embryos to the uterus is facilitated by secretion of prostaglandin E2 (PGE2) by the embryos, which relaxes the smooth muscle of the isthmus."}}]},"equine-repro--eqrepro-pregnancy--endometrial-cups-ecg-และ-accessory-cl-35-60-วัน":{"claims":[{"id":"equine-repro--eqrepro-pregnancy--endometrial-cups-ecg-และ-accessory-cl-35-60-วัน--v1","statement":"endometrial cups สร้าง chorionic gonadotrophin (eCG) ที่กระตุ้นให้เกิด secondary corpora lutea ในรังไข่แม่ม้า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-11999314","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the thickened, annulate chorionic girdle, invades the maternal endometrium to form the unique endometrial cups. These secrete a chorionic gonadotrophin that synergizes with pituitary follicle-stimulating hormone to induce secondary luteal development"}}]},"equine-repro--eqrepro-pregnancy--mid-pregnancy-40-180-วัน-และ-placentation":{"claims":[{"id":"equine-repro--eqrepro-pregnancy--mid-pregnancy-40-180-วัน-และ-placentation--v1","statement":"เมื่อ chorioallantoic placenta พัฒนา progesterone ลดลงตามการหายไปของ endometrial cups และ eCG และถูกแทนด้วย 5α-dihydroprogesterone (5α-pregnane)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31252409","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Progesterone declines as the endometrial cups and eCG disappears, replaced by 5α-dihydroprogesterone (DHP), a potent equine progesterone receptor (PR) agonist, as the chorioallantoic placenta develops."}}]},"equine-repro--eqrepro-pregnancy--late-pregnancy-180-340-วัน-และ-length-of-gestation":{"claims":[{"id":"equine-repro--eqrepro-pregnancy--late-pregnancy-180-340-วัน-และ-length-of-gestation--v1","statement":"อายุครรภ์เฉลี่ยของ Thoroughbred อยู่ราว 344 วัน และช่วง 315-388 วันให้ลูกมีชีวิตได้ทั้งหมด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12417119","locator":"abstract","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"An average gestation length of 344.1 +/- 0.49 days was evident... the gestation length range (315-388 days), all resulting in viable foals is noteworthy and of clinical importance"}}]},"equine-repro--eqrepro-pregnancy--routine-pregnancy-checks-และ-twin-management":{"claims":[{"id":"equine-repro--eqrepro-pregnancy--routine-pregnancy-checks-และ-twin-management--v1","statement":"ท้องแฝดในม้าไม่พึงประสงค์ และต้องวินิจฉัยตั้งแต่ mobility phase (ก่อน fixation ราว day 16-17) จึงจัดการ twin reduction ได้ผลดี","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38594910","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Twin gestation in the mare is undesirable and can have disastrous consequences... A pregnancy diagnosis in the mobility phase is imperative for a good outcome in the event of twin reduction."}}]},"equine-repro--eqrepro-pregnancy--routine-care-of-pregnant-mare":{"claims":[{"id":"equine-repro--eqrepro-pregnancy--routine-care-of-pregnant-mare--v1","statement":"EHV-1 ทำให้แม่ม้าท้องแท้ง และ vaccination ยังเป็นวิธีป้องกันหลัก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32172913","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Respiratory distress, abortion in pregnant mares, neurological disorders, and neonatal foal deaths represent EHV-1 infection. Despite the limited success of inactivated, subunit, live, and DNA vaccines, ... vaccination remains the prime preventive option"}}]},"equine-repro--eqrepro-pregnancy--mammary-gland-colostrum-และสัญญาณใกล้คลอด":{"claims":[{"id":"equine-repro--eqrepro-pregnancy--mammary-gland-colostrum-และสัญญาณใกล้คลอด--v1","statement":"เมื่อ calcium carbonate ในสารคัดหลั่งเต้านมก่อนคลอด ≥ 200 ppm แม่ม้าราว 51% คลอดใน 24 ชั่วโมง และ 97% ใน 72 ชั่วโมง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16727305","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"prefoaling mammary secretion calcium carbonate >/= 200 ppm) indicated that 51.4% of late term pregnant mares would foal within the ensuing 24-hour period, 84.1% within 48 hours and 97.2% within 72 hours."}}]},"equine-repro--eqrepro-pregnancy--stages-of-parturition":{"claims":[{"id":"equine-repro--eqrepro-pregnancy--stages-of-parturition--v1","statement":"การคลอดลูกใน Stage II ที่ล่าช้าเกิน 40 นาทีสัมพันธ์กับอัตราตายของลูกม้าที่เพิ่มขึ้นอย่างมีนัยสำคัญ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22594021","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A delay in foal delivery beyond 40 min of Stage II of labour was associated with a significant increase in foal mortality."}}]},"equine-repro--eqrepro-pregnancy--hormonal-regulation-และสรุปของส่วนแม่ม้า":{"claims":[{"id":"equine-repro--eqrepro-pregnancy--hormonal-regulation-และสรุปของส่วนแม่ม้า--v1","statement":"eCG จาก endometrial cups กระตุ้น luteal steroidogenesis และ DHEA จาก fetal gonad เป็นสารตั้งต้นของ oestrone sulphate จากรก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31252409","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"stimulation of luteal steroidogeneisis by equine chorionic gonadotropin (eCG) from the endometrial cups... Foetal gonadal dehydroepiandrosterone fuels placental oestrone sulphate secretion"}}]},"equine-repro--eqrepro-pregnancy--maternal-recognition-of-pregnancy-ในแม่ม้า":{"claims":[{"id":"equine-repro--eqrepro-pregnancy--maternal-recognition-of-pregnancy-ในแม่ม้า--v1","statement":"สัญญาณ maternal recognition of pregnancy ในม้ายังไม่มีการระบุตัวได้ชัดเจน โดยการทดลองที่พยายามพิสูจน์ว่า estrogen จากตัวอ่อนเป็นตัวยืดอายุ corpus luteum ให้ผลไม่สรุป ส่วนกลไกที่ยืนยันได้คือการลดการหลั่ง PGF2alpha จาก endometrium ผ่านการลด expression ของเอนไซม์สังเคราะห์ prostaglandin และการลด oxytocin receptor ตรงกับที่สไลด์บอกว่าสารตัวนี้ยังไม่ทราบชื่อ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26450499","locator":"Abstract, maternal recognition section (vol 216, pp 165-188)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"During maternal recognition of pregnancy, endometrial PGF2alpha release is attenuated, a consequence of reduced expression of key enzymes involved in prostaglandin production... Results of experiments attempting to prove that conceptus-deri"}}]}},"equine-repro--eqrepro-stallion-infect":{"equine-repro--eqrepro-stallion-infect--equine-herpesvirus-แยกให้ออกเป็นคนละโรค":{"claims":[{"id":"equine-repro--eqrepro-stallion-infect--equine-herpesvirus-แยกให้ออกเป็นคนละโรค--v1","statement":"EHV-1 ทำให้เกิดโรคระบบทางเดินหายใจ การแท้ง และความผิดปกติทางระบบประสาท ส่วน EHV-3 เป็นสาเหตุของ equine coital exanthema แยกกันชัดเจนตามที่สไลด์ระบุ (EHV-4 ทำให้เกิดโรคทางเดินหายใจและแท้งเป็นครั้งคราว)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30388626","locator":"Abstract, opening sentences (vol 526, pp 105-116)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"EHV-1 causes respiratory diseases, abortions and nervous disorders, EHV-4 causes respiratory diseases and sporadic abortion, while EHV-3 is responsible of equine coital exanthema."}},{"id":"equine-repro--eqrepro-stallion-infect--equine-herpesvirus-แยกให้ออกเป็นคนละโรค--v2","statement":"eosinophilic intranuclear inclusion body ซึ่งเป็นลักษณะเฉพาะของการติดเชื้อ herpesvirus ตรวจพบได้ในเนื้อเยื่อของลูกม้าแท้งที่ติด EHV-1 ทั้งในเซลล์กล้ามเนื้อหัวใจ macrophage เซลล์บุหลอดเลือด และเซลล์กล้ามเนื้อเรียบของผนังหลอดเลือดที่มีรอยโรค ตรงกับที่สไลด์ระบุว่าใช้ยืนยันการติดเชื้อ EHV-1","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-9179750","locator":"Abstract, Results (vol 116, issue 4, pp 379-385)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Eosinophilic intranuclear inclusion bodies characteristic of herpesvirus infection were detected in the myocardial cells and macrophages within and around the inflammatory lesions and in the endothelial cells and medial smooth muscle cells "}},{"id":"equine-repro--eqrepro-stallion-infect--equine-herpesvirus-แยกให้ออกเป็นคนละโรค--v3","statement":"ข้อควรระวังที่สไลด์ไม่ได้บอก คือ intranuclear inclusion body เป็นการยืนยันได้แต่ความไวต่ำ ในการเปรียบเทียบวิธีวินิจฉัย EHV-1 ในลูกม้าแท้ง 101 ราย พบ inclusion body เพียง 25 จาก 71 ตัวอย่างเนื้อเยื่อที่ให้ผลบวกต่อไวรัส (35.2%) การไม่พบ inclusion body จึงตัด EHV-1 ออกไม่ได้ และ immunohistochemistry มีความไวสูงกว่าการแยกเชื้อเล็กน้อย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12737042","locator":"Abstract, Results (vol 51, issue 2, pp 153-163)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Characteristic microscopic changes were seen in several organs in all cases, while intranuclear inclusion bodies could be found only in 25 (35.2%) of the 71 virus-positive tissue samples."}}]},"equine-repro--eqrepro-stallion-infect--โรคที่ติดต่อทางการผสมพันธุ์และทางน้ำเชื้อ":{"claims":[{"id":"equine-repro--eqrepro-stallion-infect--โรคที่ติดต่อทางการผสมพันธุ์และทางน้ำเชื้อ--v1","statement":"equine viral arteritis (EVA) ทำให้พ่อม้าเป็นพาหะแบบถาวร (persistent carrier state) และปล่อยไวรัสออกทางน้ำเชื้อ ซึ่งเป็นเหตุผลที่สหภาพยุโรปบังคับตรวจ EVA ในพ่อม้าที่ใช้ผสมเทียมมากว่า 30 ปี ยืนยันความสำคัญด้านการขนส่งน้ำเชื้อข้ามประเทศตามที่เฉลยข้อสอบระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38150796","locator":"Abstract, opening sentences (vol 223, article 106096)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Equine viral arteritis (EVA) can induce a persistent carrier state in stallions which then shed the virus via semen. About 30 years ago, obligatory EVA testing of stallions used for artificial insemination (AI) was implemented in the Europe"}},{"id":"equine-repro--eqrepro-stallion-infect--โรคที่ติดต่อทางการผสมพันธุ์และทางน้ำเชื้อ--v2","statement":"Taylorella equigenitalis คือเชื้อก่อโรค contagious equine metritis (CEM) และเป็นหนึ่งในสามเชื้อแบคทีเรียที่ยอมรับกันว่าเป็น venereal pathogen ที่ทำให้เกิด endometritis ในม้า (อีกสองคือ Pseudomonas aeruginosa บางสายพันธุ์ และ Klebsiella pneumoniae บาง capsule type) โดยสหราชอาณาจักรกำหนดให้ตรวจคัดกรองก่อนผสมกว่า 20,000 ตัวอย่างต่อปี ตรงกับที่เฉลยระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39103748","locator":"Abstract, opening sentences (vol 57, issue 3, pp 587-597)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Three bacteria extensively acknowledged as venereal pathogens with the potential to induce endometritis include Taylorella equigenitalis, the causative agent of contagious equine metritis (CEM), specific strains of Pseudomonas aeruginosa, a"}},{"id":"equine-repro--eqrepro-stallion-infect--โรคที่ติดต่อทางการผสมพันธุ์และทางน้ำเชื้อ--v3","statement":"dourine เป็น trypanosomosis ที่ติดต่อทางการผสมพันธุ์ (venereal transmission) โดยเชื้อ Trypanosoma equiperdum และมีอาการทั้งระบบสืบพันธุ์และระบบประสาท โดยตรวจพบเชื้อในช่องคลอด อัณฑะ ไขสันหลังส่วนปลาย และเส้นประสาท sciatic กับ obturator ยืนยันการติดต่อทางระบบสืบพันธุ์ ตรงกับที่เฉลยระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31138270","locator":"Abstract, Background and Conclusions (vol 15, issue 1, article 175)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Dourine, a venereal transmitted trypanosomosis caused by Trypanosoma equiperdum, has different clinical signs related to the reproductive and nervous system... its presence in the genital tract exemplifies the venereal transmission."}},{"id":"equine-repro--eqrepro-stallion-infect--โรคที่ติดต่อทางการผสมพันธุ์และทางน้ำเชื้อ--v4","statement":"Streptococcus equi subsp. zooepidemicus เป็นหนึ่งในเชื้อที่แยกได้บ่อยที่สุดจากมดลูกของแม่ม้าที่เป็น infectious endometritis โดยในแม่ม้าที่มี intrauterine fluid หลังผสม 55% เป็น infectious endometritis และ 81% ของกลุ่มนั้นแยกเชื้อ S. zooepidemicus ได้ นอกจากนี้การติดเชื้อแบบ clonal สัมพันธ์กับอายุมาก parity สูง และรูปทรงปากช่องคลอดที่ไม่ดี พร้อมอัตราตั้งท้องต่ำ (38%)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26300275","locator":"Abstract, Introduction and Results (vol 84, issue 8, pp 1283-1290)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Streptococcus equi subsp. zooepidemicus (S. zooepidemicus) is one of the most commonly isolated pathogens from the uterus of mares, suffering from infectious endometritis... Fifty-five percent (16 of 29) of the mares with IUF had infectious"}}]},"equine-repro--eqrepro-stallion-infect--สาเหตุของ-infertility-ในพ่อม้า-ภาพรวม":{"claims":[{"id":"equine-repro--eqrepro-stallion-infect--สาเหตุของ-infertility-ในพ่อม้า-ภาพรวม--v1","statement":"Equine coital exanthema เกิดจาก herpesvirus ที่ทำรอยโรคที่อวัยวะเพศภายนอก และติดต่อผ่านการผสมพันธุ์เป็นหลัก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-40485269","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Equine Coital Exanthema (ECE) is an endemic herpesvirus disease primarily affecting the external genitalia and impairing mating activities in horses. ... Transmission occurs primarily through mating activities"}}]},"equine-repro--eqrepro-stallion-infect--behavioural-problems":{"claims":[{"id":"equine-repro--eqrepro-stallion-infect--behavioural-problems--v1","statement":"พ่อม้าส่วนใหญ่ปรับตัวกับการจัดการได้ และปัญหาพฤติกรรมแก้ได้ด้วยการตรวจและการปรับ housing กับ handling","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27726992","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"most domestic stallions can adapt to management and breeding programs. ... This article discusses veterinary evaluation as well as housing and handling strategies for addressing stallion breeding behavior problems."}}]},"equine-repro--eqrepro-stallion-infect--problems-associated-with-ejaculation":{"claims":[{"id":"equine-repro--eqrepro-stallion-infect--problems-associated-with-ejaculation--v1","statement":"ความผิดปกติของ ejaculation ในพ่อม้าที่พบบ่อยคือ emission failure, ejaculation failure และปัสสาวะปนในน้ำเชื้อ และหลายรายมาจากปัญหา musculoskeletal หรือ psychogenic","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-1576554","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In stallions, the most common ejaculation disorders are emission and ejaculation failure, and urine contamination of semen. ... In a large percentage of cases, an ejaculation appears to be a result of musculoskeletal disorders or to be psychogenic in nature"}}]},"equine-repro--eqrepro-stallion-infect--poor-semen-quality-และ-azoospermia":{"claims":[{"id":"equine-repro--eqrepro-stallion-infect--poor-semen-quality-และ-azoospermia--v1","statement":"ใน stallion ที่ดูเหมือน ejaculate แต่ azoospermic ระดับ alkaline phosphatase ใน seminal plasma ที่ต่ำชี้ไปที่ blockage ของ excurrent duct หรือ retrograde ejaculation ส่วนระดับสูงชี้ไปที่ testicular defect","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22488664","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"If ALP activity is low, the possibility of either blockage to sperm outflow in the excurrent duct system or retrograde ejaculation should be pursued diagnostically. If ALP activity is high, the possibility of a testicular defect should be pursued diagnostically."}}]},"equine-repro--eqrepro-stallion-infect--contagious-equine-metritis-cem":{"claims":[{"id":"equine-repro--eqrepro-stallion-infect--contagious-equine-metritis-cem--v1","statement":"T. equigenitalis แพร่ทาง infected semen ที่ส่งไป และทาง fomites ที่ปนเปื้อนใน stallion collection centre","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20889687","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Shipment of infective semen and indirect venereal contact in stallion collection centers through the use of contaminated fomites were major factors in the spread of T. equigenitalis."}}]},"equine-repro--eqrepro-stallion-infect--equine-herpesvirus-type-3-equine-coital-exanthema":{"claims":[{"id":"equine-repro--eqrepro-stallion-infect--equine-herpesvirus-type-3-equine-coital-exanthema--v1","statement":"Equine coital exanthema เกิดจาก equid alphaherpesvirus 3 ติดต่อทาง direct contact ระหว่างผสมพันธุ์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34451519","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"caused by equid alphaherpesvirus 3 (EHV-3). The infection is endemic worldwide and the virus is transmitted mainly through direct contact during sexual intercourse and by contaminated instruments during reproductive maneuvers in breeding facilities."}}]},"equine-repro--eqrepro-stallion-infect--equine-viral-arteritis-eva":{"claims":[{"id":"equine-repro--eqrepro-stallion-infect--equine-viral-arteritis-eva--v1","statement":"EAV ทำให้ม้าแท้งและเกิด persistent infection ในโฮสต์ ซึ่งทำให้มีการขับไวรัสออกทางน้ำเชื้อและแพร่ทางเพศสัมพันธ์ และ EAV อยู่ใน family Arteriviridae","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-29172072","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"they both cause abortion in pregnant animals and establish persistent infection in their natural hosts, which fosters viral shedding in semen leading to sexual transmission."}}]},"equine-repro--eqrepro-stallion-infect--dourine-trypanosoma-equiperdum":{"claims":[{"id":"equine-repro--eqrepro-stallion-infect--dourine-trypanosoma-equiperdum--v1","statement":"Dourine เกิดจาก Trypanosoma equiperdum และแพร่โดยตรงจากสัตว์ตัวหนึ่งไปอีกตัวหนึ่งระหว่างผสมพันธุ์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-41200335","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Trypanosoma equiperdum is a protozoan parasite that causes the sexually transmitted disease known as \"dourine\" in horses. This chronic illness is directly spread from one animal to another during mating."}}]}},"equine-repro--eqrepro-male":{"equine-repro--eqrepro-male--breeding-soundness-examination-ของพ่อม้า":{"claims":[{"id":"equine-repro--eqrepro-male--breeding-soundness-examination-ของพ่อม้า--v1","statement":"Breeding soundness evaluation ของพ่อม้ารวมประวัติ พฤติกรรมการผสม การเก็บและตรวจน้ำเชื้อ และการตรวจโรคติดเชื้อ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-1576547","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The evaluation should include historical data about the medical aspects of the horse's performance and breeding career, observations and breeding behavior characteristics, collection and evaluation of semen, tests to determine freedom from infectious or contagious disease"}}]},"equine-repro--eqrepro-male--penis-vascular-type-urethral-process-และ-fossa-glandis":{"claims":[{"id":"equine-repro--eqrepro-male--penis-vascular-type-urethral-process-และ-fossa-glandis--v1","statement":"ใน penis ของม้าเมื่อ vasodilation จะมีเลือดเข้าเติม corpus cavernosum และ corpus spongiosum มากขึ้นตอน erection","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24049919","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"After vasodilation with mild stimulation from an electroejaculator, there was increased filling of the CCP and corpus spongiosum penis."}}]},"equine-repro--eqrepro-male--clinical-examination-ของ-penis-และ-prepuce":{"claims":[{"id":"equine-repro--eqrepro-male--clinical-examination-ของ-penis-และ-prepuce--v1","statement":"Penile prolapse ที่ยาวนานในม้าพบร่วมกับ phenothiazine tranquilizer ได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-9290825","locator":"abstract","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Prolonged penile prolapse in horses has been reported in association with administration of phenothiazine tranquilizers, trauma, neuropathies, severe general debilitation or exhaustion, starvation, rabies, herpes myeloencephalitis, equine infectious anemia, and purpura hemorrhagica."}}]},"equine-repro--eqrepro-male--diseases-of-penis-and-prepuce-และการ-swab":{"claims":[{"id":"equine-repro--eqrepro-male--diseases-of-penis-and-prepuce-และการ-swab--v1","statement":"Equine coital exanthema เป็นโรคติดต่อทางเพศสัมพันธ์ที่เกิดรอยโรคที่อวัยวะเพศภายนอก มี EHV-3 (equid alphaherpesvirus 3) เป็นสาเหตุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34451519","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Equine coital exanthema (ECE) is a highly contagious, venereally-transmitted mucocutaneous disease, characterized by the formation of papules, vesicles, pustules and ulcers on the external genital organs of mares and stallions, and caused by equid alphaherpesvirus 3 (EHV-3)."}}]},"equine-repro--eqrepro-male--scrotum-scrotal-sac":{"claims":[{"id":"equine-repro--eqrepro-male--scrotum-scrotal-sac--v1","statement":"การสร้าง sperm ของม้าพ่อพันธุ์ต้องการอุณหภูมิต่ำกว่าอุณหภูมิแกนกลางของร่างกายเล็กน้อย จึงต้องมี thermoregulation","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-37970501","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Spermatogenesis in animals such as stallions is a temperature-dependent process, ideally occurring at temperatures slightly below the core body temperature."}}]},"equine-repro--eqrepro-male--testis-testicular-descent-และ-cryptorchidism":{"claims":[{"id":"equine-repro--eqrepro-male--testis-testicular-descent-และ-cryptorchidism--v1","statement":"Cryptorchidism คือการที่ testis หนึ่งหรือสองข้างไม่ลงสู่ scrotum","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17379650","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Cryptorchidism is failure of one or both testes to descend into the scrotum."}}]},"equine-repro--eqrepro-male--spermatogenesis-และการควบคุม":{"claims":[{"id":"equine-repro--eqrepro-male--spermatogenesis-และการควบคุม--v1","statement":"Spermatogenesis แบ่งเป็น spermatocytogenesis, meiosis และ spermiogenesis","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16728209","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Activities of these three germ cells divide spermatogenesis into spermatocytogenesis, meiosis, and spermiogenesis, respectively."}}]},"equine-repro--eqrepro-male--clinical-examination-ของ-scrotum-และ-testis":{"claims":[{"id":"equine-repro--eqrepro-male--clinical-examination-ของ-scrotum-และ-testis--v1","statement":"Scrotal width ของพ่อม้ามีสหสัมพันธ์กับ daily sperm production และ daily sperm output","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-289781","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Scrotal width was correlated (P less than 0.01) with daily sperm production (r = 0.75) and daily sperm output (r = 0.55) and was generally the most repeatable measurement."}}]},"equine-repro--eqrepro-male--epididymis-และ-vas-deferens":{"claims":[{"id":"equine-repro--eqrepro-male--epididymis-และ-vas-deferens--v1","statement":"sperm จาก cauda epididymis ของพ่อม้าเก็บมาแช่แข็งและประเมินความสามารถในการปฏิสนธิได้ และหลังละลายอาจดีกว่า sperm จาก ejaculate ในพ่อม้า subfertile","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-42863643","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"After thawing, epididymal sperm from subfertile stallions exhibited better sperm kinetics, structural and functional viability, and fertility than ejaculated sperm."}}]},"equine-repro--eqrepro-male--accessory-sex-glands-gel-fraction-และ-ampullary-obstruction":{"claims":[{"id":"equine-repro--eqrepro-male--accessory-sex-glands-gel-fraction-และ-ampullary-obstruction--v1","statement":"seminal plasma ของพ่อม้ามีสารที่มาจาก epididymis และ accessory glands","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20546178","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Seminal plasma (SP) contains several types of compounds derived from the epididymides and accessory glands."}}]},"equine-repro--eqrepro-male--stallion-behaviors-และการผสมตามธรรมชาติ":{"claims":[{"id":"equine-repro--eqrepro-male--stallion-behaviors-และการผสมตามธรรมชาติ--v1","statement":"ปัญหาพฤติกรรมการผสมของพ่อม้ามีตั้งแต่ความสนใจทางเพศไม่พอหรือไม่คงที่ ไปจนถึงตอบสนองรุนแรงเกินไป","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27726992","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the problems can range from inadequate or variable sexual interest and response to overenthusiastic or aggressive response beyond the ability of the handlers to safely direct and control."}}]}},"equine-repro--eqrepro-ai":{"equine-repro--eqrepro-ai--stallion-selection-และโรคที่ติดต่อทางการผสมพันธุ์":{"claims":[{"id":"equine-repro--eqrepro-ai--stallion-selection-และโรคที่ติดต่อทางการผสมพันธุ์--v1","statement":"EVA ทำให้พ่อม้าเป็น carrier ถาวรที่ขับไวรัสออกทางน้ำเชื้อ และสหภาพยุโรปบังคับตรวจ EVA ในพ่อม้าที่ใช้ AI","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38150796","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Equine viral arteritis (EVA) can induce a persistent carrier state in stallions which then shed the virus via semen. About 30 years ago, obligatory EVA testing of stallions used for artificial insemination (AI) was implemented in the European Union."}}]},"equine-repro--eqrepro-ai--semen-collection-และ-artificial-vagina":{"claims":[{"id":"equine-repro--eqrepro-ai--semen-collection-และ-artificial-vagina--v1","statement":"น้ำเชื้อพ่อม้าเก็บได้ด้วย artificial vagina บน phantom หรือแม่ม้า หรือด้วยการกระตุ้นด้วยยา และวิธีเก็บมีผลต่อปริมาตรและความเข้มข้น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-37835729","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Semen can be collected with an artificial vagina on a phantom or a mare, by electro-ejaculation under anesthesia, or after pharmacological induction. The collection method influences the semen volume and concentration"}}]},"equine-repro--eqrepro-ai--ejaculation-และส่วนประกอบของน้ำเชื้อ":{"claims":[{"id":"equine-repro--eqrepro-ai--ejaculation-และส่วนประกอบของน้ำเชื้อ--v1","statement":"การ ejaculate ประกอบด้วย emission ของ sperm และของเหลวจาก accessory glands เข้า urethra แล้วบีบออกผ่าน urethra","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-1576554","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"important events of ejaculation include emission of sperm and the accessory gland fluids into the urethra, simultaneous closure of the bladder neck, and forceful ejaculation of the combined semen through the urethra."}}]},"equine-repro--eqrepro-ai--semen-evaluation":{"claims":[{"id":"equine-repro--eqrepro-ai--semen-evaluation--v1","statement":"Motility เป็นพารามิเตอร์หลักของการประเมินน้ำเชื้อพ่อม้า และสัมพันธ์กับ fertility ของน้ำเชื้อสดหรือแช่แข็ง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-37835729","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Motility analysis remains a core parameter, as it is associated with fresh or frozen dose fertility."}}]},"equine-repro--eqrepro-ai--handling-semen-extender-และน้ำเชื้อ-3-ชนิด":{"claims":[{"id":"equine-repro--eqrepro-ai--handling-semen-extender-และน้ำเชื้อ-3-ชนิด--v1","statement":"การผสมเทียมในม้าอาศัยน้ำเชื้อแช่เย็นที่ขนส่งเป็นหลัก และ sperm ม้าไวต่อความเย็นจนจำกัดระยะเวลาเก็บ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-42800388","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Artificial insemination in horses largely relies on cooled transported semen, but stallion spermatozoa are highly sensitive to cold stress, limiting storage duration."}}]},"equine-repro--eqrepro-ai--frozen-semen":{"claims":[{"id":"equine-repro--eqrepro-ai--frozen-semen--v1","statement":"พ่อม้าแต่ละตัวมีคุณภาพน้ำเชื้อหลังแช่แข็งต่างกันมาก ซึ่งเป็นข้อจำกัดสำคัญของอุตสาหกรรมม้า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27417910","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Stallion-to-stallion variability in the quality of cryopreserved ejaculates postthaw affects the commercial acceptability of frozen semen and thus is a major constraint for the equine industry."}}]},"equine-repro--eqrepro-ai--mare-preparation-เวลาผสม-และเทคนิค-intrauterine-insemination":{"claims":[{"id":"equine-repro--eqrepro-ai--mare-preparation-เวลาผสม-และเทคนิค-intrauterine-insemination--v1","statement":"ในม้าการตกไข่เหนี่ยวนำได้ด้วย hCG, rLH หรือ GnRH analogue (deslorelin) และตกไข่ราว 36 ชั่วโมงหลังให้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-18554709","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Ovulation is routinely induced with human chorionic gonadotropin (hCG), recombinant LH (rLH), or the GnRH analogue Deslorelin. On average, ovulation occurs approximately 36h after treatment"}}]},"equine-repro--eqrepro-ai--post-insemination-management":{"claims":[{"id":"equine-repro--eqrepro-ai--post-insemination-management--v1","statement":"การตั้งท้องแฝดในแม่ม้าไม่พึงประสงค์ และการตรวจ ultrasound ระยะแรกทำให้จัดการลดเหลือตัวเดียวได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34624812","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"multiple pregnancies in mare are always undesirable, early ultrasound diagnosis makes possible management of twin pregnancies and extra embryo removal."}}]}},"equine-repro--eqrepro-surgery":{"equine-repro--eqrepro-surgery--castration-วัตถุประสงค์และช่วงเวลาที่ทำ":{"claims":[{"id":"equine-repro--eqrepro-surgery--castration-วัตถุประสงค์และช่วงเวลาที่ทำ--v1","statement":"การตอนใช้เป็นมาตรการแก้พฤติกรรมทางเพศและความก้าวร้าวที่ไม่พึงประสงค์ในม้าพ่อพันธุ์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-4038698","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"When castration was examined as a therapeutic measure to eliminate sexual and aggressive behavior in stallions in which the behavior had become objectionable, it was found that the operation was effective on sexual behavior and aggression toward people in 60% to 70% of horses"}}]},"equine-repro--eqrepro-surgery--standing-castration-กับ-recumbent-castration":{"claims":[{"id":"equine-repro--eqrepro-surgery--standing-castration-กับ-recumbent-castration--v1","statement":"ม้าปกติตอนได้ทั้งแบบยืนด้วย sedation และ regional anaesthesia หรือแบบนอนด้วย general anaesthesia ส่วน cryptorchid ทำดีที่สุดภายใต้ general anaesthesia ในสถานที่ผ่าตัด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10451725","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Castration of the normal horse can be performed using sedation and regional anaesthesia while the horse is standing, or under general anaesthesia when it is recumbent. Castration of cryptorchid horses is best performed under general anaesthesia at a surgical facility."}}]},"equine-repro--eqrepro-surgery--castration-anesthesia-restraint-และ-local-anesthesia":{"claims":[{"id":"equine-repro--eqrepro-surgery--castration-anesthesia-restraint-และ-local-anesthesia--v1","statement":"ในการตอนม้าที่ได้ general anaesthesia มีการฉีดยาชาเข้า testis ข้างละ 10 mL (lidocaine เทียบกับ mepivacaine)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32090383","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Thirty-four stallions were anaesthetised using xylazine-ketamine and randomly selected to receive 10 mL either lidocaine or mepivacaine injected into each testicle."}}]},"equine-repro--eqrepro-surgery--open-castration-technique":{"claims":[{"id":"equine-repro--eqrepro-surgery--open-castration-technique--v1","statement":"ใน ambulatory practice ของสวีเดน การตอนแบบยืนด้วย open technique โดยไม่เย็บแผลเป็นที่นิยม ส่วนในโรงพยาบาลนิยม closed technique แบบเย็บแผล","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-43026618","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In Sweden, standing, open castration with un-sutured incisions was preferred in ambulatory practice, whereas a closed, sutured technique dominated in the hospitals."}}]},"equine-repro--eqrepro-surgery--closed-castration-technique":{"claims":[{"id":"equine-repro--eqrepro-surgery--closed-castration-technique--v1","statement":"ความเสี่ยง evisceration ดูเหมือนต่ำถ้าปิด parietal tunic เมื่อจบการผ่าตัด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38993145","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Evisceration was most commonly reported in draught breeds and Standardbreds, and the risk appeared low if the parietal tunic was closed at the end of surgery."}}]},"equine-repro--eqrepro-surgery--emasculator":{"claims":[{"id":"equine-repro--eqrepro-surgery--emasculator--v1","statement":"Serra และ Reimer emasculator ใช้บ่อยในการตอนม้า แต่ต่างกันที่ jaw profile และกลไกการห้ามเลือด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28636747","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The Serra and Reimer emasculators are frequently used in equine orchiectomy. They differ in jaw profile and the mechanism by which they achieve haemostasis."}}]},"equine-repro--eqrepro-surgery--post-operative-management-หลัง-castration":{"claims":[{"id":"equine-repro--eqrepro-surgery--post-operative-management-หลัง-castration--v1","statement":"อาการบวมหรือ oedema เป็นภาวะแทรกซ้อนที่รายงานบ่อยที่สุดหลังตอนม้า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38993145","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Eighteen different complications were reported, with swelling or oedema being the most common."}}]},"equine-repro--eqrepro-surgery--post-operative-complication-หลัง-castration":{"claims":[{"id":"equine-repro--eqrepro-surgery--post-operative-complication-หลัง-castration--v1","statement":"ภาวะแทรกซ้อนหลังตอนม้าที่รายงานได้แก่ บวม เลือดออกมาก eventration funiculitis peritonitis hydrocele และ penile damage","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10451725","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Reported complications of castration include postoperative swelling, excessive haemorrhage, eventration, funiculitis, peritonitis, hydrocele, penile damage and continued stallion-like behaviour."}}]},"equine-repro--eqrepro-surgery--cryptorchid":{"claims":[{"id":"equine-repro--eqrepro-surgery--cryptorchid--v1","statement":"cryptorchidectomy ทำด้วย standing laparoscopy หรือ open inguinal orchiectomy ภายใต้ general anaesthesia","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33371184","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Cryptorchidectomy was achieved with standing laparoscopy (44/70 cases, 62.8%), or with open inguinal orchiectomy in general anesthesia (26/70 cases, 37.2%)."}}]},"equine-repro--eqrepro-surgery--tumor-of-penis-และ-penile-circumcision-reefing":{"claims":[{"id":"equine-repro--eqrepro-surgery--tumor-of-penis-และ-penile-circumcision-reefing--v1","statement":"เนื้องอกของ penis และ prepuce ในม้า ได้แก่ squamous cell carcinoma, sarcoid และ melanoma","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26464915","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The diagnosed neoplasms were penile and preputial squamous cell carcinomas (SCCs; n = 15); sarcoid (n = 4); a-fibrosarcoma; and a melanoma."}}]},"equine-repro--eqrepro-surgery--amputation-of-penis":{"claims":[{"id":"equine-repro--eqrepro-surgery--amputation-of-penis--v1","statement":"partial phallectomy แบบ modified Vinsot ใช้ latex tourniquet และสร้าง linear urethrostomy","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20590499","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Modifications to the original technique included creation of a linear urethrostomy, alteration of the location and shape of the urethrostomy, application of a latex tourniquet"}}]},"equine-repro--eqrepro-surgery--caslick-s-operation":{"claims":[{"id":"equine-repro--eqrepro-surgery--caslick-s-operation--v1","statement":"แม่ม้าที่ช่องคลอด (vulva) กว้างเสี่ยง pneumovagina ซึ่งทำให้ fertility ลดลง และรักษาด้วย Caslick operation ที่ลดขนาดช่อง vulva","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10343366","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Mares with a large vulvar orifice have an increased risk of pneumovagina, which is associated with reduced fertility. Treatment is by means of the Caslick operation, by which size of the vulvar orifice is reduced."}}]},"equine-repro--eqrepro-surgery--perineal-laceration-3-ระดับ-และ-recto-vaginal-fistula":{"claims":[{"id":"equine-repro--eqrepro-surgery--perineal-laceration-3-ระดับ-และ-recto-vaginal-fistula--v1","statement":"การผ่าตัดซ่อม third-degree perineal laceration หรือ rectovestibular fistula ในแม่ม้า ทำให้ 24 จาก 32 ตัวที่ถูกผสมตั้งท้องได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-3882647","locator":"abstract","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Of 32 mares bred, 24 became pregnant, suggesting that surgical repair is indicated in any mare with sufficient genetic potential."}}]},"equine-repro--eqrepro-surgery--endoscopic-removal-ของ-endometrial-cyst":{"claims":[{"id":"equine-repro--eqrepro-surgery--endoscopic-removal-ของ-endometrial-cyst--v1","statement":"endometrial cyst ที่อยู่ใน lumen ตัดออกได้ในม้ายืนด้วย endoscope และลวดที่คล้องที่ฐาน cyst แล้วตัดด้วยไฟฟ้า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10573803","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Endometrial cysts located in the lumen can be removed surgically from the standing mare. After placement of the endoscope, a wire is placed, via the biopsy channel, around the base of cyst, which is then cut through by cauterization."}}]},"equine-repro--eqrepro-surgery--caesarean-section":{"claims":[{"id":"equine-repro--eqrepro-surgery--caesarean-section--v1","statement":"Dystocia พบไม่บ่อยในม้า และ caesarean section หรือการดึงลูกออกทำในราว 13.9% ของเคส","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39394153","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Dystocia is rare in horses, but is life-threatening for mares and foals... A caesarean section or an extraction was performed in 13.9% of the cases."}}]}}};
